pub fn op_compress_decompress(data: &[u8], iters: u64) -> String {
    let mut digest: u64 = 0;
    let mut last_err: i32 = 0;

    for _ in 0..iters {
        unsafe {
            let src_size = data.len() as i32;
            if src_size == 0 {
                // Empty input: fold zeros
                digest = fold(digest, 0);
                continue;
            }
            let bound = LZ4_compressBound(src_size);
            if bound <= 0 {
                last_err = -1;
                digest = fold(digest, 0);
                continue;
            }
            let mut compressed: Vec<u8> = vec![0u8; bound as usize];
            let comp_size = LZ4_compress_default(
                data.as_ptr() as *const i8,
                compressed.as_mut_ptr() as *mut i8,
                src_size,
                bound,
            );
            if comp_size <= 0 {
                last_err = comp_size;
                digest = fold(digest, comp_size as u64);
                continue;
            }
            let mut decompressed: Vec<u8> = vec![0u8; src_size as usize];
            let decomp_size = LZ4_decompress_safe(
                compressed.as_ptr() as *const i8,
                decompressed.as_mut_ptr() as *mut i8,
                comp_size,
                src_size,
            );
            if decomp_size < 0 {
                last_err = decomp_size;
                digest = fold(digest, decomp_size as u64);
                continue;
            }
            let iter_digest = fold(
                fold(comp_size as u64, decomp_size as u64),
                xor_fold_bytes(&decompressed[..decomp_size as usize]),
            );
            digest = fold(digest, iter_digest);
        }
    }
    format!("op=compress_decompress err={} digest={:016x}", last_err, digest)
}

