pub fn gen_seeds(dir: &str) -> Vec<String> {
    let mut lines = Vec::new();

    // Pattern 1: 1024 bytes, 0..255 repeated 4 times
    let mut pat1 = Vec::with_capacity(1024);
    for _ in 0..4 {
        for b in 0u8..=255 {
            pat1.push(b);
        }
    }

    // Pattern 2: 2048 bytes, 255..0 repeated 8 times
    let mut pat2 = Vec::with_capacity(2048);
    for _ in 0..8 {
        for b in (0u8..=255).rev() {
            pat2.push(b);
        }
    }

    let op_names = [
        "compress_decompress",
        "compress_hc_decompress",
        "frame_round_trip",
        "streaming_compress",
        "xxhash_digest",
    ];

    for op in &op_names {
        let path1 = format!("{}/{}.1.bin", dir, op);
        let path2 = format!("{}/{}.2.bin", dir, op);
        fs::write(&path1, &pat1).unwrap();
        fs::write(&path2, &pat2).unwrap();
        lines.push(format!("seed {} {}", op, path1));
        lines.push(format!("seed {} {}", op, path2));
    }

    lines
}

