    let mut lines = Vec::new();

    // Generate a large buffer: 512 KB of semi-compressible data
    let size = 512 * 1024;
    let mut big = Vec::with_capacity(size);
    let mut val: u32 = 0x12345678;
    for _ in 0..size {
        // Simple PRNG for deterministic semi-random data
        val = val.wrapping_mul(1103515245).wrapping_add(12345);
        big.push((val >> 16) as u8);
