// ── op: frame_dict_round_trip ──
pub fn op_frame_dict_round_trip(data: &[u8], iters: u64) -> String {
    let mut digest: u64 = 0;
    let mut last_err: u64 = 0;
    for _ in 0..iters {
        unsafe {
            let dict_data = b"frame_dictionary_for_testing_0123456789abcdef";
