            let s32b = XXH32_createState();
            iter = fold(iter, (!s32.is_null()) as u64);
            iter = fold(iter, (!s32b.is_null()) as u64);

            if !s32.is_null() && !s32b.is_null() {
                let rc = XXH32_reset(s32, seed32);
                iter = fold(iter, rc as u64);
                last_err = rc;

                let p1 = data.len() / 3;
                let p2 = (data.len() * 2) / 3;
                let rc1 = XXH32_update(
                    s32,
                    if p1 == 0 {
                        ptr::null()
                    } else {
                        data[..p1].as_ptr() as *const _
                    },
                    p1,
                );
                let rc2 = XXH32_update(
                    s32,
                    if p2 > p1 {
                        data[p1..p2].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    p2.saturating_sub(p1),
                );
                XXH32_copyState(s32b, s32);
                let rc3 = XXH32_update(
                    s32,
                    if data.len() > p2 {
                        data[p2..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p2),
                );
                let rc4 = XXH32_update(
                    s32b,
                    if data.len() > p2 {
                        data[p2..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p2),
                );
                iter = fold(iter, rc1 as u64);
                iter = fold(iter, rc2 as u64);
                iter = fold(iter, rc3 as u64);
                iter = fold(iter, rc4 as u64);
                last_err = rc4;

                let d32 = XXH32_digest(s32);
                let d32b = XXH32_digest(s32b);
                iter = fold(iter, d32 as u64);
                iter = fold(iter, d32b as u64);
                iter = fold(iter, (d32 == h32) as u64);
                iter = fold(iter, (d32b == h32) as u64);

                let mut canon32 = MaybeUninit::<XXH32_canonical_t>::zeroed();
                XXH32_canonicalFromHash(canon32.as_mut_ptr(), d32);
                let rt32 = XXH32_hashFromCanonical(canon32.as_ptr());
                iter = fold(iter, rt32 as u64);
                iter = fold(iter, (rt32 == d32) as u64);

                let frc1 = XXH32_freeState(s32);
                let frc2 = XXH32_freeState(s32b);
                iter = fold(iter, frc1 as u64);
                iter = fold(iter, frc2 as u64);
            } else {
                if !s32.is_null() {
                    let frc = XXH32_freeState(s32);
                    iter = fold(iter, frc as u64);
                }
                if !s32b.is_null() {
                    let frc = XXH32_freeState(s32b);
                    iter = fold(iter, frc as u64);
                }
            }

            let s64 = XXH64_createState();
            let s64b = XXH64_createState();
            iter = fold(iter, (!s64.is_null()) as u64);
            iter = fold(iter, (!s64b.is_null()) as u64);

            if !s64.is_null() && !s64b.is_null() {
                let rc = XXH64_reset(s64, seed64);
                iter = fold(iter, rc as u64);
                last_err = rc;

                let p1 = data.len() / 4;
                let p2 = data.len() / 2;
                let p3 = (data.len() * 3) / 4;
                let rc1 = XXH64_update(
                    s64,
                    if p1 == 0 {
                        ptr::null()
                    } else {
                        data[..p1].as_ptr() as *const _
                    },
                    p1,
                );
                let rc2 = XXH64_update(
                    s64,
                    if p2 > p1 {
                        data[p1..p2].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    p2.saturating_sub(p1),
                );
                let rc3 = XXH64_update(
                    s64,
                    if p3 > p2 {
                        data[p2..p3].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    p3.saturating_sub(p2),
                );
                XXH64_copyState(s64b, s64);
                let rc4 = XXH64_update(
                    s64,
                    if data.len() > p3 {
                        data[p3..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p3),
                );
                let rc5 = XXH64_update(
                    s64b,
                    if data.len() > p3 {
                        data[p3..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p3),
                );
                iter = fold(iter, rc1 as u64);
                iter = fold(iter, rc2 as u64);
                iter = fold(iter, rc3 as u64);
                iter = fold(iter, rc4 as u64);
                iter = fold(iter, rc5 as u64);
                last_err = rc5;

                let d64 = XXH64_digest(s64);
                let d64b = XXH64_digest(s64b);
                iter = fold(iter, d64);
                iter = fold(iter, d64b);
                iter = fold(iter, (d64 == h64) as u64);
                iter = fold(iter, (d64b == h64) as u64);

                let mut canon64 = MaybeUninit::<XXH64_canonical_t>::zeroed();
                XXH64_canonicalFromHash(canon64.as_mut_ptr(), d64);
                let rt64 = XXH64_hashFromCanonical(canon64.as_ptr());
                iter = fold(iter, rt64);
                iter = fold(iter, (rt64 == d64) as u64);

                let frc1 = XXH64_freeState(s64);
                let frc2 = XXH64_freeState(s64b);
                iter = fold(iter, frc1 as u64);
                iter = fold(iter, frc2 as u64);
            } else {
                if !s64.is_null() {
                    let frc = XXH64_freeState(s64);
                    iter = fold(iter, frc as u64);
                }
                if !s64b.is_null() {
                    let frc = XXH64_freeState(s64b);
                    iter = fold(iter, frc as u64);
                }
            }

            iter = fold(iter, checksum_bytes(data));
            digest = fold(digest, iter);
        }
    }

    format!("op=xxhash_streaming err={} digest={:016x}", last_err, digest)
}

pub fn ops() -> Vec<(&'static str, fn(&[u8], u64) -> String)> {
    vec![
        (
            "lz4_block_roundtrip",
            op_lz4_block_roundtrip as fn(&[u8], u64) -> String,
        ),
        (
            "lz4_frame_decompress",
