        ),
        (
            "lz4_hc_block_roundtrip",
            op_lz4_hc_block_roundtrip as fn(&[u8], u64) -> String,
        ),
        (
            "xxhash_streaming",
            op_xxhash_streaming as fn(&[u8], u64) -> String,
