    ]
}

pub fn gen_seeds(dir: &str) -> Vec<String> {
    let mut lines = Vec::new();

    let raw1 = realistic_text_payload(220);
    let raw2 = realistic_binary_payload(320);

    for (op, idx, bytes) in [
        ("lz4_block_roundtrip", 1usize, &raw1),
        ("lz4_block_roundtrip", 2usize, &raw2),
        ("lz4_hc_block_roundtrip", 1usize, &raw1),
        ("lz4_hc_block_roundtrip", 2usize, &raw2),
        ("xxhash_streaming", 1usize, &raw1),
        ("xxhash_streaming", 2usize, &raw2),
    ] {
        let path = format!("{}/{}.{}.bin", dir, op, idx);
        fs::write(&path, bytes).unwrap();
        lines.push(format!("seed {} {}", op, path));
    }

    let frame1 = make_frame_bytes(&raw1);
    let frame2 = make_frame_bytes(&raw2);

    for (idx, bytes) in [(1usize, &frame1), (2usize, &frame2)] {
        let path = format!("{}/lz4_frame_decompress.{}.bin", dir, idx);
        fs::write(&path, bytes).unwrap();
        lines.push(format!("seed {} {}", "lz4_frame_decompress", path));
    }

    lines
}

pub fn gen_perf(dir: &str) -> Vec<String> {
    let mut lines = Vec::new();

    let big_text = realistic_text_payload(40_000);
    let big_bin = realistic_binary_payload(45_000);
    let big_mix = {
        let mut v = Vec::with_capacity(big_text.len() + big_bin.len());
        v.extend_from_slice(&big_text);
        v.extend_from_slice(&big_bin);
        v
    };

    for (op, bytes) in [
        ("lz4_block_roundtrip", &big_mix),
        ("lz4_hc_block_roundtrip", &big_mix),
        ("xxhash_streaming", &big_mix),
    ] {
        let path = format!("{}/{}.perf.bin", dir, op);
        fs::write(&path, bytes).unwrap();
        lines.push(format!("perf {} {}", op, path));
    }

    let frame = make_frame_bytes(&big_mix);
    let path = format!("{}/lz4_frame_decompress.perf.bin", dir);
    fs::write(&path, &frame).unwrap();
    lines.push(format!("perf {} {}", "lz4_frame_decompress", path));

    lines
}
