fn fold(acc: u64, x: u64) -> u64 {
    acc.rotate_left(7) ^ x.wrapping_mul(0x9E37_79B1_85EB_CA87)
}

fn checksum_bytes(data: &[u8]) -> u64 {
    let mut acc = 0u64;
    for &b in data {
        acc = fold(acc, b as u64);
    }
    fold(acc, data.len() as u64)
}

fn as_c_int_len(n: usize) -> i32 {
    if n > i32::MAX as usize {
        i32::MAX
    } else {
        n as i32
    }
}

fn split_for_dict(data: &[u8]) -> (usize, usize) {
    let n = data.len();
    if n == 0 {
        return (0, 0);
    }
    let dict = n.min(65536).min(n / 3 + (n > 2) as usize);
    let rem = n.saturating_sub(dict);
    let b1 = if rem == 0 { 0 } else { rem / 2 + (rem % 2) };
    (dict, b1)
}

