        if i % 16 == 0 {
            v.extend_from_slice(
                b"{\"event\":\"config_refresh\",\"keys\":[\"feature_a\",\"feature_b\",\"timeout_ms\"],\"ok\":true}\n",
            );
        }
        if i % 11 == 0 {
            v.extend_from_slice(b"cookie=session=abcdef0123456789; secure; httponly; samesite=lax\n");
