unsafe fn zeroed_prefs() -> LZ4F_preferences_t {
    MaybeUninit::<LZ4F_preferences_t>::zeroed().assume_init()
}

unsafe fn zeroed_copts() -> LZ4F_compressOptions_t {
    MaybeUninit::<LZ4F_compressOptions_t>::zeroed().assume_init()
}

unsafe fn zeroed_dopts() -> LZ4F_decompressOptions_t {
    MaybeUninit::<LZ4F_decompressOptions_t>::zeroed().assume_init()
}

unsafe fn zeroed_custom_mem() -> LZ4F_CustomMem {
    MaybeUninit::<LZ4F_CustomMem>::zeroed().assume_init()
}

fn make_frame_bytes(src: &[u8]) -> Vec<u8> {
    unsafe {
        let mut prefs = zeroed_prefs();
        prefs.compressionLevel = 3;
        prefs.autoFlush = 0;
        prefs.frameInfo.blockMode = LZ4F_blockLinked;
        prefs.frameInfo.blockSizeID = LZ4F_max256KB;
        prefs.frameInfo.contentChecksumFlag = LZ4F_contentChecksumEnabled;
        prefs.frameInfo.blockChecksumFlag = LZ4F_blockChecksumEnabled;
        prefs.frameInfo.contentSize = src.len() as u64;

        let bound = LZ4F_compressFrameBound(src.len(), &prefs);
        if bound == 0 {
            return Vec::new();
        }
        let mut out = vec![0u8; bound];
        let written = LZ4F_compressFrame(
            out.as_mut_ptr() as *mut _,
            out.len(),
            if src.is_empty() {
                ptr::null()
            } else {
                src.as_ptr() as *const _
            },
            src.len(),
            &prefs as *const _,
        );
        if LZ4F_isError(written) != 0 || written > out.len() {
            Vec::new()
        } else {
            out.truncate(written);
            out
        }
    }
}

fn make_frame_bytes_streaming(src: &[u8], dict: &[u8], use_cdict: bool) -> Vec<u8> {
    unsafe {
        let mut prefs = zeroed_prefs();
        prefs.compressionLevel = 9;
        prefs.autoFlush = 0;
        prefs.frameInfo.blockMode = LZ4F_blockLinked;
        prefs.frameInfo.blockSizeID = LZ4F_max256KB;
        prefs.frameInfo.contentChecksumFlag = LZ4F_contentChecksumEnabled;
        prefs.frameInfo.blockChecksumFlag = LZ4F_blockChecksumEnabled;
        prefs.frameInfo.contentSize = src.len() as u64;

        let mut cctx: *mut LZ4F_cctx = ptr::null_mut();
        let rc = LZ4F_createCompressionContext(&mut cctx as *mut *mut _, LZ4F_getVersion());
        if LZ4F_isError(rc) != 0 || cctx.is_null() {
            return Vec::new();
        }

        let mut out = vec![0u8; LZ4F_compressFrameBound(src.len(), &prefs).saturating_add(1024)];
        let mut pos = 0usize;

        let mut header = vec![0u8; 256];
        let hsz = if use_cdict {
            let cdict = LZ4F_createCDict(
                if dict.is_empty() {
                    ptr::null()
                } else {
                    dict.as_ptr() as *const _
                },
                dict.len(),
            );
            if cdict.is_null() {
                LZ4F_compressBegin(
                    cctx,
                    header.as_mut_ptr() as *mut _,
                    header.len(),
                    &prefs as *const _,
                )
            } else {
                let r = LZ4F_compressBegin_usingCDict(
                    cctx,
                    header.as_mut_ptr() as *mut _,
                    header.len(),
                    cdict,
                    &prefs as *const _,
                );
                LZ4F_freeCDict(cdict);
                r
            }
        } else {
            LZ4F_compressBegin_usingDict(
                cctx,
                header.as_mut_ptr() as *mut _,
                header.len(),
                if dict.is_empty() {
                    ptr::null()
                } else {
                    dict.as_ptr() as *const _
                },
                dict.len(),
                &prefs as *const _,
            )
        };

        if LZ4F_isError(hsz) != 0 || hsz > header.len() {
            let _ = LZ4F_freeCompressionContext(cctx);
            return Vec::new();
        }
        out[pos..pos + hsz].copy_from_slice(&header[..hsz]);
        pos += hsz;

        let mut copts = zeroed_copts();
        copts.stableSrc = 1;

        let mut off = 0usize;
        let chunk = 32 * 1024usize;
        while off < src.len() {
            let end = (off + chunk).min(src.len());
            let part = &src[off..end];
            let need = LZ4F_compressBound(part.len(), &prefs).saturating_add(64);
            if pos + need > out.len() {
                out.resize(pos + need, 0);
            }
            let wsz = LZ4F_compressUpdate(
                cctx,
                out[pos..].as_mut_ptr() as *mut _,
                out.len() - pos,
                if part.is_empty() {
                    ptr::null()
                } else {
                    part.as_ptr() as *const _
                },
                part.len(),
                &copts as *const _,
            );
            if LZ4F_isError(wsz) != 0 {
                let _ = LZ4F_freeCompressionContext(cctx);
                return Vec::new();
            }
            pos += wsz;
            off = end;
        }

        let fneed = LZ4F_compressBound(0, &prefs).saturating_add(128);
        if pos + fneed > out.len() {
            out.resize(pos + fneed, 0);
        }
        let fsz = LZ4F_flush(
            cctx,
            out[pos..].as_mut_ptr() as *mut _,
            out.len() - pos,
            &copts as *const _,
        );
        if LZ4F_isError(fsz) != 0 {
            let _ = LZ4F_freeCompressionContext(cctx);
            return Vec::new();
        }
        pos += fsz;

        let esz = LZ4F_compressEnd(
            cctx,
            out[pos..].as_mut_ptr() as *mut _,
            out.len() - pos,
            &copts as *const _,
        );
        let _ = LZ4F_freeCompressionContext(cctx);
        if LZ4F_isError(esz) != 0 {
            return Vec::new();
        }
        pos += esz;
        out.truncate(pos);
        out
    }
}

fn op_lz4_block_roundtrip(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0i32;

    for _ in 0..iters {
        unsafe {
            let mut iter = 0u64;
            iter = fold(iter, LZ4_versionNumber() as u64);
            let vstr = LZ4_versionString();
            iter = fold(iter, (!vstr.is_null()) as u64);
            if !vstr.is_null() {
                iter = fold(iter, checksum_bytes(CStr::from_ptr(vstr).to_bytes()));
            }

            let src_len = as_c_int_len(data.len());
            let bound = LZ4_compressBound(src_len);
            let state_sz = LZ4_sizeofState();
            let stream_state_sz = LZ4_sizeofStreamState();
            let ring = LZ4_decoderRingBufferSize(64 * 1024);
            iter = fold(iter, src_len as u64);
            iter = fold(iter, bound as u64);
            iter = fold(iter, state_sz as u64);
            iter = fold(iter, stream_state_sz as u64);
            iter = fold(iter, ring as u64);

            if bound <= 0 || state_sz <= 0 {
                last_err = if bound <= 0 { bound } else { state_sz };
                digest = fold(digest, iter ^ 1);
                continue;
            }

            let mut compressed = vec![0u8; bound as usize];
            let csz = LZ4_compress_default(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                compressed.as_mut_ptr() as *mut i8,
                src_len,
                bound,
            );
            last_err = csz;
            iter = fold(iter, csz as u64);

            if csz > 0 {
                let mut decomp = vec![0u8; data.len()];
                let dsz = LZ4_decompress_safe(
                    compressed.as_ptr() as *const i8,
                    if decomp.is_empty() {
                        ptr::null_mut()
                    } else {
                        decomp.as_mut_ptr() as *mut i8
                    },
                    csz,
                    src_len,
                );
                last_err = dsz;
                iter = fold(iter, dsz as u64);
                iter = fold(iter, (dsz == src_len && decomp.as_slice() == data) as u64);
                if dsz > 0 {
                    iter = fold(iter, checksum_bytes(&decomp[..dsz as usize]));
                }

                let mut decomp_fast = vec![0u8; data.len()];
                let fsz = LZ4_decompress_fast(
                    compressed.as_ptr() as *const i8,
                    if decomp_fast.is_empty() {
                        ptr::null_mut()
                    } else {
                        decomp_fast.as_mut_ptr() as *mut i8
                    },
                    src_len,
                );
                iter = fold(iter, fsz as u64);
                last_err = fsz;
                if src_len >= 0 {
                    iter = fold(iter, checksum_bytes(&decomp_fast));
                }

                let target = (data.len() / 2 + data.len() % 2).min(data.len());
                let mut partial = vec![0u8; data.len()];
                let psz = LZ4_decompress_safe_partial(
                    compressed.as_ptr() as *const i8,
                    if partial.is_empty() {
                        ptr::null_mut()
                    } else {
                        partial.as_mut_ptr() as *mut i8
                    },
                    csz,
                    as_c_int_len(target),
                    src_len,
                );
                iter = fold(iter, psz as u64);
                last_err = psz;
                if psz > 0 {
                    iter = fold(iter, checksum_bytes(&partial[..psz as usize]));
                }

                if data.len() <= 65536 {
                    let mut p64 = vec![0u8; data.len()];
                    let s64 = LZ4_decompress_safe_withPrefix64k(
                        compressed.as_ptr() as *const i8,
                        if p64.is_empty() {
                            ptr::null_mut()
                        } else {
                            p64.as_mut_ptr() as *mut i8
                        },
                        csz,
                        src_len,
                    );
                    iter = fold(iter, s64 as u64);
                    if s64 > 0 {
                        iter = fold(iter, checksum_bytes(&p64[..s64 as usize]));
                    }

                    let mut p64f = vec![0u8; data.len()];
                    let f64 = LZ4_decompress_fast_withPrefix64k(
                        compressed.as_ptr() as *const i8,
                        if p64f.is_empty() {
                            ptr::null_mut()
                        } else {
                            p64f.as_mut_ptr() as *mut i8
                        },
                        src_len,
                    );
                    iter = fold(iter, f64 as u64);
                    if f64 >= 0 {
                        iter = fold(iter, checksum_bytes(&p64f));
                    }
                }
            }

            let mut state = vec![0u8; state_sz as usize];
            let mut c2 = vec![0u8; bound.max(1) as usize];
            let c2sz = LZ4_compress_fast_extState(
                state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                c2.as_mut_ptr() as *mut i8,
                src_len,
                bound,
                2,
            );
            iter = fold(iter, c2sz as u64);
            last_err = c2sz;

            let c3sz = LZ4_compress_fast_extState_fastReset(
                state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                c2.as_mut_ptr() as *mut i8,
                src_len,
                bound,
                4,
            );
            iter = fold(iter, c3sz as u64);
            last_err = c3sz;

            let c4sz = LZ4_compress_fast(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                c2.as_mut_ptr() as *mut i8,
                src_len,
                bound,
                3,
            );
            iter = fold(iter, c4sz as u64);
            last_err = c4sz;

            let mut src_size_ptr = src_len;
            let target_dst = (bound / 2).max(1);
            let c5sz = LZ4_compress_destSize(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                c2.as_mut_ptr() as *mut i8,
                &mut src_size_ptr,
                target_dst,
            );
            iter = fold(iter, c5sz as u64);
            iter = fold(iter, src_size_ptr as u64);
            last_err = c5sz;

            let mut src_size_ptr2 = src_len;
            let c6sz = LZ4_compress_destSize_extState(
                state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                c2.as_mut_ptr() as *mut i8,
                &mut src_size_ptr2,
                target_dst,
                5,
            );
            iter = fold(iter, c6sz as u64);
            iter = fold(iter, src_size_ptr2 as u64);
            last_err = c6sz;

            let c7sz = LZ4_compress_limitedOutput(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                c2.as_mut_ptr() as *mut i8,
                src_len,
                target_dst,
            );
            iter = fold(iter, c7sz as u64);
            last_err = c7sz;

            let c8sz = LZ4_compress(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                c2.as_mut_ptr() as *mut i8,
                src_len,
            );
            iter = fold(iter, c8sz as u64);
            last_err = c8sz;

            let c9sz = LZ4_compress_withState(
                state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                c2.as_mut_ptr() as *mut i8,
                src_len,
            );
            iter = fold(iter, c9sz as u64);
            last_err = c9sz;

            let c10sz = LZ4_compress_limitedOutput_withState(
                state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                c2.as_mut_ptr() as *mut i8,
                src_len,
                target_dst,
            );
            iter = fold(iter, c10sz as u64);
            last_err = c10sz;

            let (dict_len, b1_len) = split_for_dict(data);
            let b2_len = data.len().saturating_sub(dict_len + b1_len);
            iter = fold(iter, dict_len as u64);
            iter = fold(iter, b1_len as u64);
            iter = fold(iter, b2_len as u64);

            let enc = LZ4_createStream();
            let dec = LZ4_createStreamDecode();
            iter = fold(iter, (!enc.is_null()) as u64);
            iter = fold(iter, (!dec.is_null()) as u64);

            let mut stack_stream =
                vec![0u8; size_of::<lz4_raw::src::lz4::LZ4_stream_t>()];
            let init_stream = LZ4_initStream(stack_stream.as_mut_ptr() as *mut _, stack_stream.len());
            iter = fold(iter, (!init_stream.is_null()) as u64);
            if !init_stream.is_null() {
                LZ4_resetStream(init_stream);
                LZ4_resetStream_fast(init_stream);
            }

            if !enc.is_null() && !dec.is_null() {
                let dict_ptr = if dict_len == 0 {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                };
                let loaded = LZ4_loadDict(enc, dict_ptr, as_c_int_len(dict_len));
                let loaded_slow = LZ4_loadDictSlow(enc, dict_ptr, as_c_int_len(dict_len));
                let setd = LZ4_setStreamDecode(dec, dict_ptr, as_c_int_len(dict_len));
                iter = fold(iter, loaded as u64);
                iter = fold(iter, loaded_slow as u64);
                iter = fold(iter, setd as u64);
                last_err = if setd < 0 { setd } else { loaded_slow };

                let dict_stream = LZ4_createStream();
                iter = fold(iter, (!dict_stream.is_null()) as u64);
                if !dict_stream.is_null() {
                    let _ = LZ4_loadDict(dict_stream, dict_ptr, as_c_int_len(dict_len));
                    LZ4_attach_dictionary(enc, dict_stream);
                }

                let mut saved = vec![0u8; dict_len.max(1)];
                let saved_sz =
                    LZ4_saveDict(enc, saved.as_mut_ptr() as *mut i8, as_c_int_len(saved.len()));
                iter = fold(iter, saved_sz as u64);

                let mut stream_ok = true;

                if b1_len > 0 {
                    let src1 = &data[dict_len..dict_len + b1_len];
                    let cap1 = LZ4_compressBound(as_c_int_len(src1.len()));
                    iter = fold(iter, cap1 as u64);
                    if cap1 > 0 {
                        let mut c1 = vec![0u8; cap1 as usize];
                        let c1sz = LZ4_compress_fast_continue(
                            enc,
                            src1.as_ptr() as *const i8,
                            c1.as_mut_ptr() as *mut i8,
                            as_c_int_len(src1.len()),
                            cap1,
                            1,
                        );
                        iter = fold(iter, c1sz as u64);
                        last_err = c1sz;
                        if c1sz > 0 {
                            let mut d1 = vec![0u8; src1.len()];
                            let d1sz = LZ4_decompress_safe_continue(
                                dec,
                                c1.as_ptr() as *const i8,
                                d1.as_mut_ptr() as *mut i8,
                                c1sz,
                                as_c_int_len(d1.len()),
                            );
                            iter = fold(iter, d1sz as u64);
                            let d1f = LZ4_decompress_fast_continue(
                                dec,
                                c1.as_ptr() as *const i8,
                                d1.as_mut_ptr() as *mut i8,
                                as_c_int_len(d1.len()),
                            );
                            iter = fold(iter, d1f as u64);
                            last_err = d1sz;
                            let ok1 = d1sz == as_c_int_len(src1.len()) && d1.as_slice() == src1;
                            iter = fold(iter, ok1 as u64);
                            if d1sz > 0 {
                                iter = fold(iter, checksum_bytes(&d1[..d1sz as usize]));
                            }
                            stream_ok &= ok1;

                            let mut c1b = vec![0u8; cap1 as usize];
                            let c1lsz = LZ4_compress_limitedOutput_continue(
                                enc,
                                src1.as_ptr() as *const i8,
                                c1b.as_mut_ptr() as *mut i8,
                                as_c_int_len(src1.len()),
                                cap1,
                            );
                            iter = fold(iter, c1lsz as u64);

                            let mut c1c = vec![0u8; cap1 as usize];
                            let c1csz = LZ4_compress_continue(
                                enc,
                                src1.as_ptr() as *const i8,
                                c1c.as_mut_ptr() as *mut i8,
                                as_c_int_len(src1.len()),
                            );
                            iter = fold(iter, c1csz as u64);
                        } else {
                            stream_ok = false;
                        }
                    } else {
                        stream_ok = false;
                    }
                }

                if b2_len > 0 {
                    let src2 = &data[dict_len + b1_len..];
                    let cap2 = LZ4_compressBound(as_c_int_len(src2.len()));
                    iter = fold(iter, cap2 as u64);
                    if cap2 > 0 {
                        let mut c2s = vec![0u8; cap2 as usize];
                        let c2sz = LZ4_compress_fast_continue(
                            enc,
                            src2.as_ptr() as *const i8,
                            c2s.as_mut_ptr() as *mut i8,
                            as_c_int_len(src2.len()),
                            cap2,
                            2,
                        );
                        iter = fold(iter, c2sz as u64);
                        last_err = c2sz;
                        if c2sz > 0 {
                            let mut d2 = vec![0u8; src2.len()];
                            let d2sz = LZ4_decompress_safe_continue(
                                dec,
                                c2s.as_ptr() as *const i8,
                                d2.as_mut_ptr() as *mut i8,
                                c2sz,
                                as_c_int_len(d2.len()),
                            );
                            iter = fold(iter, d2sz as u64);
                            last_err = d2sz;
                            let ok2 = d2sz == as_c_int_len(src2.len()) && d2.as_slice() == src2;
                            iter = fold(iter, ok2 as u64);
                            if d2sz > 0 {
                                iter = fold(iter, checksum_bytes(&d2[..d2sz as usize]));
                            }
                            stream_ok &= ok2;
                        } else {
                            stream_ok = false;
                        }
                    } else {
                        stream_ok = false;
                    }
                }

                if dict_len > 0 && b1_len > 0 {
                    let src1 = &data[dict_len..dict_len + b1_len];
                    let cap = LZ4_compressBound(as_c_int_len(src1.len()));
                    if cap > 0 {
                        let mut cext = vec![0u8; cap as usize];
                        let cextsz = LZ4_compress_forceExtDict(
                            enc,
                            src1.as_ptr() as *const i8,
                            cext.as_mut_ptr() as *mut i8,
                            as_c_int_len(src1.len()),
                        );
                        iter = fold(iter, cextsz as u64);
                        if cextsz > 0 {
                            let mut dout = vec![0u8; src1.len()];
                            let dsd = LZ4_decompress_safe_usingDict(
                                cext.as_ptr() as *const i8,
                                dout.as_mut_ptr() as *mut i8,
                                cextsz,
                                as_c_int_len(dout.len()),
                                data.as_ptr() as *const i8,
                                as_c_int_len(dict_len),
                            );
                            iter = fold(iter, dsd as u64);
                            if dsd > 0 {
                                iter = fold(iter, checksum_bytes(&dout[..dsd as usize]));
                            }

                            let mut dout2 = vec![0u8; src1.len()];
                            let dfd = LZ4_decompress_fast_usingDict(
                                cext.as_ptr() as *const i8,
                                dout2.as_mut_ptr() as *mut i8,
                                as_c_int_len(dout2.len()),
                                data.as_ptr() as *const i8,
                                as_c_int_len(dict_len),
                            );
                            iter = fold(iter, dfd as u64);
                            iter = fold(iter, checksum_bytes(&dout2));

                            let mut dout3 = vec![0u8; src1.len()];
                            let dsfe = LZ4_decompress_safe_forceExtDict(
                                cext.as_ptr() as *const i8,
                                dout3.as_mut_ptr() as *mut i8,
                                cextsz,
                                as_c_int_len(dout3.len()),
                                data.as_ptr() as *const _,
                                dict_len,
                            );
                            iter = fold(iter, dsfe as u64);

                            let mut dout4 = vec![0u8; src1.len()];
                            let part_target = as_c_int_len(src1.len() / 2 + src1.len() % 2);
                            let dsp = LZ4_decompress_safe_partial_usingDict(
                                cext.as_ptr() as *const i8,
                                dout4.as_mut_ptr() as *mut i8,
                                cextsz,
                                part_target,
                                as_c_int_len(dout4.len()),
                                data.as_ptr() as *const i8,
                                as_c_int_len(dict_len),
                            );
                            iter = fold(iter, dsp as u64);

                            let mut dout5 = vec![0u8; src1.len()];
                            let dsp2 = LZ4_decompress_safe_partial_forceExtDict(
                                cext.as_ptr() as *const i8,
                                dout5.as_mut_ptr() as *mut i8,
                                cextsz,
                                part_target,
                                as_c_int_len(dout5.len()),
                                data.as_ptr() as *const _,
                                dict_len,
                            );
                            iter = fold(iter, dsp2 as u64);
                        }
                    }
                }

                iter = fold(iter, stream_ok as u64);

                if !dict_stream.is_null() {
                    let rc = LZ4_freeStream(dict_stream);
                    iter = fold(iter, rc as u64);
                }
            }

            let mut legacy_state = vec![0u8; stream_state_sz.max(1) as usize];
            let reset_state =
                LZ4_resetStreamState(legacy_state.as_mut_ptr() as *mut _, ptr::null_mut());
            iter = fold(iter, reset_state as u64);

            let legacy_ctx = LZ4_create(ptr::null_mut());
            iter = fold(iter, (!legacy_ctx.is_null()) as u64);
            if !legacy_ctx.is_null() {
                let slid = LZ4_slideInputBuffer(legacy_ctx);
                iter = fold(iter, (!slid.is_null()) as u64);
            }

            if !enc.is_null() {
                let rc = LZ4_freeStream(enc);
                iter = fold(iter, rc as u64);
            }
            if !dec.is_null() {
                let rc = LZ4_freeStreamDecode(dec);
                iter = fold(iter, rc as u64);
            }

            digest = fold(digest, iter);
        }
    }

    format!("op=lz4_block_roundtrip err={} digest={:016x}", last_err, digest)
}

fn op_lz4_frame_decompress(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0u64;

    for _ in 0..iters {
        unsafe {
            let mut iter = 0u64;
            let mut dctx: *mut LZ4F_dctx = ptr::null_mut();
            let create_rc =
                LZ4F_createDecompressionContext(&mut dctx as *mut *mut _, LZ4F_getVersion());
            iter = fold(iter, create_rc as u64);
            last_err = create_rc as u64;

            let dctx2 =
                LZ4F_createDecompressionContext_advanced(zeroed_custom_mem(), LZ4F_getVersion());
            iter = fold(iter, (!dctx2.is_null()) as u64);
            if !dctx2.is_null() {
                iter = fold(iter, LZ4F_dctx_size(dctx2) as u64);
                let frc = LZ4F_freeDecompressionContext(dctx2);
                iter = fold(iter, frc as u64);
            }

            if LZ4F_isError(create_rc) != 0 || dctx.is_null() {
                digest = fold(digest, iter ^ 3);
                continue;
            }

            iter = fold(iter, LZ4F_dctx_size(dctx) as u64);

            let hdr = LZ4F_headerSize(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const _
                },
                data.len(),
            );
            iter = fold(iter, hdr as u64);
            if LZ4F_isError(hdr) != 0 {
                last_err = hdr as u64;
                let code = LZ4F_getErrorCode(hdr);
                let name = LZ4F_getErrorName(hdr);
                iter = fold(iter, code as u64);
                iter = fold(iter, (!name.is_null()) as u64);
                if !name.is_null() {
                    iter = fold(iter, checksum_bytes(CStr::from_ptr(name).to_bytes()));
                }
            }

            let mut fi = MaybeUninit::<LZ4F_frameInfo_t>::zeroed();
            let mut src_sz = data.len();
            let info_rc = LZ4F_getFrameInfo(
                dctx,
                fi.as_mut_ptr(),
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const _
                },
                &mut src_sz,
            );
            iter = fold(iter, src_sz as u64);
            iter = fold(iter, info_rc as u64);
            last_err = info_rc as u64;

            let mut produced = Vec::<u8>::new();
            let mut consumed = src_sz.min(data.len());
            if LZ4F_isError(info_rc) == 0 {
                let fi = fi.assume_init();
                iter = fold(iter, fi.blockSizeID as u64);
                iter = fold(iter, fi.blockMode as u64);
                iter = fold(iter, fi.contentChecksumFlag as u64);
                iter = fold(iter, fi.frameType as u64);
                iter = fold(iter, fi.contentSize);
                iter = fold(iter, fi.dictID as u64);
                iter = fold(iter, fi.blockChecksumFlag as u64);
                iter = fold(iter, LZ4F_getBlockSize(fi.blockSizeID) as u64);

                let mut next_hint = info_rc;
                let mut steps = 0u64;
                while consumed < data.len() && steps < 1_000_000 {
                    steps += 1;
                    let mut dst_chunk = vec![0u8; 64 * 1024];
                    let mut dst_sz = dst_chunk.len();
                    let mut src_part = data.len() - consumed;
                    let rc = LZ4F_decompress(
                        dctx,
                        dst_chunk.as_mut_ptr() as *mut _,
                        &mut dst_sz,
                        data[consumed..].as_ptr() as *const _,
                        &mut src_part,
                        ptr::null(),
                    );
                    iter = fold(iter, src_part as u64);
                    iter = fold(iter, dst_sz as u64);
                    iter = fold(iter, rc as u64);
                    last_err = rc as u64;

                    if dst_sz > 0 {
                        produced.extend_from_slice(&dst_chunk[..dst_sz]);
                    }
                    consumed = consumed.saturating_add(src_part);
                    next_hint = rc;

                    if LZ4F_isError(rc) != 0 || rc == 0 || (src_part == 0 && dst_sz == 0) {
                        break;
                    }
                }
                iter = fold(iter, next_hint as u64);

                LZ4F_resetDecompressionContext(dctx);
                let mut produced2 = Vec::<u8>::new();
                let mut consumed2 = 0usize;
                let mut steps2 = 0u64;
                let mut dopts = zeroed_dopts();
                dopts.stableDst = 1;
                while consumed2 < data.len() && steps2 < 1_000_000 {
                    steps2 += 1;
                    let mut dst_chunk = vec![0u8; 32 * 1024];
                    let mut dst_sz = dst_chunk.len();
                    let mut src_part = data.len() - consumed2;
                    let rc = LZ4F_decompress_usingDict(
                        dctx,
                        dst_chunk.as_mut_ptr() as *mut _,
                        &mut dst_sz,
                        data[consumed2..].as_ptr() as *const _,
                        &mut src_part,
                        ptr::null(),
                        0,
                        &dopts as *const _,
                    );
                    iter = fold(iter, src_part as u64);
                    iter = fold(iter, dst_sz as u64);
                    iter = fold(iter, rc as u64);
                    if dst_sz > 0 {
                        produced2.extend_from_slice(&dst_chunk[..dst_sz]);
                    }
                    consumed2 = consumed2.saturating_add(src_part);
                    if LZ4F_isError(rc) != 0 || rc == 0 || (src_part == 0 && dst_sz == 0) {
                        break;
                    }
                }
                iter = fold(iter, produced2.len() as u64);
                iter = fold(iter, checksum_bytes(&produced2));
            }

            iter = fold(iter, consumed as u64);
            iter = fold(iter, produced.len() as u64);
            iter = fold(iter, checksum_bytes(&produced));

            let free_rc = LZ4F_freeDecompressionContext(dctx);
            iter = fold(iter, free_rc as u64);
            if LZ4F_isError(free_rc) != 0 {
                last_err = free_rc as u64;
            }

            digest = fold(digest, iter);
        }
    }

    format!("op=lz4_frame_decompress err={} digest={:016x}", last_err, digest)
}

fn op_lz4_hc_block_roundtrip(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0i32;

    for _ in 0..iters {
        unsafe {
            let mut iter = 0u64;
            let state_sz = LZ4_sizeofStateHC();
            let stream_state_sz = LZ4_sizeofStreamStateHC();
            iter = fold(iter, state_sz as u64);
            iter = fold(iter, stream_state_sz as u64);
            last_err = state_sz;

            let src_len = as_c_int_len(data.len());
            let bound = LZ4_compressBound(src_len);
            iter = fold(iter, bound as u64);

            if bound <= 0 {
                last_err = bound;
                digest = fold(digest, iter ^ 5);
                continue;
            }

            let mut compressed = vec![0u8; bound as usize];
            let csz = LZ4_compress_HC(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                compressed.as_mut_ptr() as *mut i8,
                src_len,
                bound,
                9,
            );
            iter = fold(iter, csz as u64);
            last_err = csz;

            if csz > 0 {
                let mut decomp = vec![0u8; data.len()];
                let dsz = LZ4_decompress_safe(
                    compressed.as_ptr() as *const i8,
                    if decomp.is_empty() {
                        ptr::null_mut()
                    } else {
                        decomp.as_mut_ptr() as *mut i8
                    },
                    csz,
                    src_len,
                );
                iter = fold(iter, dsz as u64);
                last_err = dsz;
                let ok = dsz == src_len && decomp.as_slice() == data;
                iter = fold(iter, ok as u64);
                if dsz > 0 {
                    iter = fold(iter, checksum_bytes(&decomp[..dsz as usize]));
                }
            }

            let mut hc_state = vec![0u8; state_sz.max(1) as usize];
            let mut out = vec![0u8; bound as usize];
            let e1 = LZ4_compress_HC_extStateHC(
                hc_state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                src_len,
                bound,
                10,
            );
            iter = fold(iter, e1 as u64);
            let e2 = LZ4_compress_HC_extStateHC_fastReset(
                hc_state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                src_len,
                bound,
                11,
            );
            iter = fold(iter, e2 as u64);

            let mut src_size_ptr = src_len;
            let e3 = LZ4_compress_HC_destSize(
                hc_state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                &mut src_size_ptr,
                (bound / 2).max(1),
                12,
            );
            iter = fold(iter, e3 as u64);
            iter = fold(iter, src_size_ptr as u64);

            let e4 = LZ4_compressHC(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                src_len,
            );
            iter = fold(iter, e4 as u64);
            let e5 = LZ4_compressHC_limitedOutput(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                src_len,
                (bound / 2).max(1),
            );
            iter = fold(iter, e5 as u64);
            let e6 = LZ4_compressHC2(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                src_len,
                6,
            );
            iter = fold(iter, e6 as u64);
            let e7 = LZ4_compressHC2_limitedOutput(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                src_len,
                (bound / 2).max(1),
                7,
            );
            iter = fold(iter, e7 as u64);

            let e8 = LZ4_compressHC_withStateHC(
                hc_state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                src_len,
            );
            iter = fold(iter, e8 as u64);
            let e9 = LZ4_compressHC_limitedOutput_withStateHC(
                hc_state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                src_len,
                (bound / 2).max(1),
            );
            iter = fold(iter, e9 as u64);
            let e10 = LZ4_compressHC2_withStateHC(
                hc_state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                src_len,
                8,
            );
            iter = fold(iter, e10 as u64);
            let e11 = LZ4_compressHC2_limitedOutput_withStateHC(
                hc_state.as_mut_ptr() as *mut _,
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                src_len,
                (bound / 2).max(1),
                9,
            );
            iter = fold(iter, e11 as u64);

            let mut hc_stream_mem =
                vec![0u8; size_of::<lz4_raw::src::lz4hc::LZ4_streamHC_t>()];
            let hc_init =
                LZ4_initStreamHC(hc_stream_mem.as_mut_ptr() as *mut _, hc_stream_mem.len());
            iter = fold(iter, (!hc_init.is_null()) as u64);
            if !hc_init.is_null() {
                LZ4_resetStreamHC(hc_init, 5);
                LZ4_resetStreamHC_fast(hc_init, 6);
                LZ4_setCompressionLevel(hc_init, 7);
                LZ4_favorDecompressionSpeed(hc_init, 1);
            }

            let (dict_len, b1_len) = split_for_dict(data);
            let stream = LZ4_createStreamHC();
            iter = fold(iter, (!stream.is_null()) as u64);

            if !stream.is_null() {
                LZ4_resetStreamHC(stream, 9);
                LZ4_resetStreamHC_fast(stream, 10);
                LZ4_setCompressionLevel(stream, 11);
                LZ4_favorDecompressionSpeed(stream, 0);
                let loaded = LZ4_loadDictHC(
                    stream,
                    if dict_len == 0 {
                        ptr::null()
                    } else {
                        data.as_ptr() as *const i8
                    },
                    as_c_int_len(dict_len),
                );
                iter = fold(iter, loaded as u64);
                last_err = loaded;

                let dict_stream = LZ4_createStreamHC();
                iter = fold(iter, (!dict_stream.is_null()) as u64);
                if !dict_stream.is_null() {
                    LZ4_resetStreamHC(dict_stream, 12);
                    let _ = LZ4_loadDictHC(
                        dict_stream,
                        if dict_len == 0 {
                            ptr::null()
                        } else {
                            data.as_ptr() as *const i8
                        },
                        as_c_int_len(dict_len),
                    );
                    LZ4_attach_HC_dictionary(stream, dict_stream);
                }

                if b1_len > 0 {
                    let src1 = &data[dict_len..dict_len + b1_len];
                    let cap1 = LZ4_compressBound(as_c_int_len(src1.len()));
                    iter = fold(iter, cap1 as u64);
                    if cap1 > 0 {
                        let mut c1 = vec![0u8; cap1 as usize];
                        let c1sz = LZ4_compress_HC_continue(
                            stream,
                            src1.as_ptr() as *const i8,
                            c1.as_mut_ptr() as *mut i8,
                            as_c_int_len(src1.len()),
                            cap1,
                        );
                        iter = fold(iter, c1sz as u64);
                        let c1sz_old = LZ4_compressHC_continue(
                            stream,
                            src1.as_ptr() as *const i8,
                            c1.as_mut_ptr() as *mut i8,
                            as_c_int_len(src1.len()),
                        );
                        iter = fold(iter, c1sz_old as u64);
                        let c1lim_old = LZ4_compressHC_limitedOutput_continue(
                            stream,
                            src1.as_ptr() as *const i8,
                            c1.as_mut_ptr() as *mut i8,
                            as_c_int_len(src1.len()),
                            cap1,
                        );
                        iter = fold(iter, c1lim_old as u64);

                        let mut src1_ptr = as_c_int_len(src1.len());
                        let c1dst = LZ4_compress_HC_continue_destSize(
                            stream,
                            src1.as_ptr() as *const i8,
                            c1.as_mut_ptr() as *mut i8,
                            &mut src1_ptr,
                            (cap1 / 2).max(1),
                        );
                        iter = fold(iter, c1dst as u64);
                        iter = fold(iter, src1_ptr as u64);

                        if c1sz > 0 {
                            let mut d1 = vec![0u8; src1.len()];
                            let d1sz = LZ4_decompress_safe(
                                c1.as_ptr() as *const i8,
                                d1.as_mut_ptr() as *mut i8,
                                c1sz,
                                as_c_int_len(d1.len()),
                            );
                            iter = fold(iter, d1sz as u64);
                            if d1sz > 0 {
                                iter = fold(iter, checksum_bytes(&d1[..d1sz as usize]));
                            }
                        }

                        let mut saved = vec![0u8; dict_len.max(1)];
                        let sdh = LZ4_saveDictHC(
                            stream,
                            saved.as_mut_ptr() as *mut i8,
                            as_c_int_len(saved.len()),
                        );
                        iter = fold(iter, sdh as u64);
                    }
                }

                if !dict_stream.is_null() {
                    let frc = LZ4_freeStreamHC(dict_stream);
                    iter = fold(iter, frc as u64);
                }

                let frc = LZ4_freeStreamHC(stream);
                iter = fold(iter, frc as u64);
            }

            let reset_state =
                LZ4_resetStreamStateHC(hc_state.as_mut_ptr() as *mut _, ptr::null_mut());
            iter = fold(iter, reset_state as u64);

            let legacy_hc = LZ4_createHC(ptr::null());
            iter = fold(iter, (!legacy_hc.is_null()) as u64);
            if !legacy_hc.is_null() {
                let part = data.len() / 2;
                let srca = &data[..part];
                let capa = LZ4_compressBound(as_c_int_len(srca.len()));
                if capa > 0 {
                    let mut ca = vec![0u8; capa as usize];
                    let a1 = LZ4_compressHC2_continue(
                        legacy_hc,
                        if srca.is_empty() {
                            ptr::null()
                        } else {
                            srca.as_ptr() as *const i8
                        },
                        ca.as_mut_ptr() as *mut i8,
                        as_c_int_len(srca.len()),
                        5,
                    );
                    iter = fold(iter, a1 as u64);
                    let a2 = LZ4_compressHC2_limitedOutput_continue(
                        legacy_hc,
                        if srca.is_empty() {
                            ptr::null()
                        } else {
                            srca.as_ptr() as *const i8
                        },
                        ca.as_mut_ptr() as *mut i8,
                        as_c_int_len(srca.len()),
                        capa,
                        6,
                    );
                    iter = fold(iter, a2 as u64);
                }
                let slid = LZ4_slideInputBufferHC(legacy_hc);
                iter = fold(iter, (!slid.is_null()) as u64);
                let frc = LZ4_freeHC(legacy_hc);
                iter = fold(iter, frc as u64);
            }

            digest = fold(digest, iter);
        }
    }

    format!("op=lz4_hc_block_roundtrip err={} digest={:016x}", last_err, digest)
}

fn op_lz4_frame_compress_roundtrip(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0u64;

    for _ in 0..iters {
        unsafe {
            let mut iter = 0u64;
            iter = fold(iter, LZ4F_getVersion() as u64);
            iter = fold(iter, LZ4F_compressionLevel_max() as u64);

            let mut prefs = zeroed_prefs();
            prefs.compressionLevel = 9;
            prefs.autoFlush = 0;
            prefs.frameInfo.blockMode = LZ4F_blockLinked;
            prefs.frameInfo.blockSizeID = LZ4F_max256KB;
            prefs.frameInfo.contentChecksumFlag = LZ4F_contentChecksumEnabled;
            prefs.frameInfo.blockChecksumFlag = LZ4F_blockChecksumEnabled;
            prefs.frameInfo.contentSize = data.len() as u64;
            prefs.frameInfo.dictID = 0x1234_5678;

            let bound = LZ4F_compressFrameBound(data.len(), &prefs as *const _);
            let upd_bound = LZ4F_compressBound(data.len() / 2 + 1, &prefs as *const _);
            iter = fold(iter, bound as u64);
            iter = fold(iter, upd_bound as u64);

            let dict_len = data.len().min(8192);
            let dict = &data[..dict_len];

            let cdict = LZ4F_createCDict(
                if dict.is_empty() {
                    ptr::null()
                } else {
                    dict.as_ptr() as *const _
                },
                dict.len(),
            );
            let cdict2 = LZ4F_createCDict_advanced(
                zeroed_custom_mem(),
                if dict.is_empty() {
                    ptr::null()
                } else {
                    dict.as_ptr() as *const _
                },
                dict.len(),
            );
            iter = fold(iter, (!cdict.is_null()) as u64);
            iter = fold(iter, (!cdict2.is_null()) as u64);

            let mut cctx: *mut LZ4F_cctx = ptr::null_mut();
            let crc = LZ4F_createCompressionContext(&mut cctx as *mut *mut _, LZ4F_getVersion());
            iter = fold(iter, crc as u64);
            last_err = crc as u64;

            let cctx2 =
                LZ4F_createCompressionContext_advanced(zeroed_custom_mem(), LZ4F_getVersion());
            iter = fold(iter, (!cctx2.is_null()) as u64);
            if !cctx2.is_null() {
                iter = fold(iter, LZ4F_cctx_size(cctx2) as u64);
                let frc = LZ4F_freeCompressionContext(cctx2);
                iter = fold(iter, frc as u64);
            }

            if LZ4F_isError(crc) != 0 || cctx.is_null() {
                if !cdict.is_null() {
                    LZ4F_freeCDict(cdict);
                }
                if !cdict2.is_null() {
                    LZ4F_freeCDict(cdict2);
                }
                digest = fold(digest, iter ^ 9);
                continue;
            }

            iter = fold(iter, LZ4F_cctx_size(cctx) as u64);

            let mut out = vec![0u8; bound.saturating_add(4096)];
            let mut pos = 0usize;
            let mut hdr = vec![0u8; 256];

            let h1 = LZ4F_compressBegin(
                cctx,
                hdr.as_mut_ptr() as *mut _,
                hdr.len(),
                &prefs as *const _,
            );
            iter = fold(iter, h1 as u64);
            if LZ4F_isError(h1) == 0 && h1 <= hdr.len() {
                out[pos..pos + h1].copy_from_slice(&hdr[..h1]);
                pos += h1;
            }
            last_err = h1 as u64;

            let mut copts = zeroed_copts();
            copts.stableSrc = 1;

            let split = data.len() / 3;
            let split2 = (data.len() * 2) / 3;
            for part in [&data[..split], &data[split..split2]] {
                let need = LZ4F_compressBound(part.len(), &prefs as *const _).saturating_add(64);
                if pos + need > out.len() {
                    out.resize(pos + need, 0);
                }
                let wsz = LZ4F_compressUpdate(
                    cctx,
                    out[pos..].as_mut_ptr() as *mut _,
                    out.len() - pos,
                    if part.is_empty() {
                        ptr::null()
                    } else {
                        part.as_ptr() as *const _
                    },
                    part.len(),
                    &copts as *const _,
                );
                iter = fold(iter, wsz as u64);
                last_err = wsz as u64;
                if LZ4F_isError(wsz) == 0 {
                    pos += wsz;
                }
            }

            let tail = &data[split2..];
            let need = LZ4F_compressBound(tail.len(), &prefs as *const _).saturating_add(64);
            if pos + need > out.len() {
                out.resize(pos + need, 0);
            }
            let usz = LZ4F_uncompressedUpdate(
                cctx,
                out[pos..].as_mut_ptr() as *mut _,
                out.len() - pos,
                if tail.is_empty() {
                    ptr::null()
                } else {
                    tail.as_ptr() as *const _
                },
                tail.len(),
                &copts as *const _,
            );
            iter = fold(iter, usz as u64);
            last_err = usz as u64;
            if LZ4F_isError(usz) == 0 {
                pos += usz;
            }

            let fsz = LZ4F_flush(
                cctx,
                out[pos..].as_mut_ptr() as *mut _,
                out.len() - pos,
                &copts as *const _,
            );
            iter = fold(iter, fsz as u64);
            last_err = fsz as u64;
            if LZ4F_isError(fsz) == 0 {
                pos += fsz;
            }

            let esz = LZ4F_compressEnd(
                cctx,
                out[pos..].as_mut_ptr() as *mut _,
                out.len() - pos,
                &copts as *const _,
            );
            iter = fold(iter, esz as u64);
            last_err = esz as u64;
            if LZ4F_isError(esz) == 0 {
                pos += esz;
            }
            out.truncate(pos);

            let mut one_shot = vec![0u8; bound.max(1)];
            let one_sz = LZ4F_compressFrame(
                one_shot.as_mut_ptr() as *mut _,
                one_shot.len(),
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const _
                },
                data.len(),
                &prefs as *const _,
            );
            iter = fold(iter, one_sz as u64);
            if LZ4F_isError(one_sz) == 0 && one_sz <= one_shot.len() {
                one_shot.truncate(one_sz);
                iter = fold(iter, checksum_bytes(&one_shot));
            }

            if !cdict.is_null() {
                let mut cdict_out = vec![0u8; bound.max(1)];
                let cdict_sz = LZ4F_compressFrame_usingCDict(
                    cctx,
                    cdict_out.as_mut_ptr() as *mut _,
                    cdict_out.len(),
                    if data.is_empty() {
                        ptr::null()
                    } else {
                        data.as_ptr() as *const _
                    },
                    data.len(),
                    cdict,
                    &prefs as *const _,
                );
                iter = fold(iter, cdict_sz as u64);
                if LZ4F_isError(cdict_sz) == 0 && cdict_sz <= cdict_out.len() {
                    cdict_out.truncate(cdict_sz);
                    iter = fold(iter, checksum_bytes(&cdict_out));
                }
            }

            if !cdict2.is_null() {
                let mut hdr2 = vec![0u8; 256];
                let h2 = LZ4F_compressBegin_usingCDict(
                    cctx,
                    hdr2.as_mut_ptr() as *mut _,
                    hdr2.len(),
                    cdict2,
                    &prefs as *const _,
                );
                iter = fold(iter, h2 as u64);
            }

            let mut hdr3 = vec![0u8; 256];
            let h3 = LZ4F_compressBegin_usingDict(
                cctx,
                hdr3.as_mut_ptr() as *mut _,
                hdr3.len(),
                if dict.is_empty() {
                    ptr::null()
                } else {
                    dict.as_ptr() as *const _
                },
                dict.len(),
                &prefs as *const _,
            );
            iter = fold(iter, h3 as u64);

            let mut dctx: *mut LZ4F_dctx = ptr::null_mut();
            let drc = LZ4F_createDecompressionContext(&mut dctx as *mut *mut _, LZ4F_getVersion());
            iter = fold(iter, drc as u64);
            if LZ4F_isError(drc) == 0 && !dctx.is_null() {
                let mut produced = Vec::new();
                let mut consumed = 0usize;
                while consumed < out.len() {
                    let mut dst = vec![0u8; 64 * 1024];
                    let mut dst_sz = dst.len();
                    let mut src_sz = out.len() - consumed;
                    let rc = LZ4F_decompress(
                        dctx,
                        dst.as_mut_ptr() as *mut _,
                        &mut dst_sz,
                        out[consumed..].as_ptr() as *const _,
                        &mut src_sz,
                        ptr::null(),
                    );
                    iter = fold(iter, rc as u64);
                    iter = fold(iter, src_sz as u64);
                    iter = fold(iter, dst_sz as u64);
                    if dst_sz > 0 {
                        produced.extend_from_slice(&dst[..dst_sz]);
                    }
                    consumed += src_sz;
                    if LZ4F_isError(rc) != 0 || rc == 0 || (src_sz == 0 && dst_sz == 0) {
                        break;
                    }
                }
                iter = fold(iter, produced.len() as u64);
                iter = fold(iter, checksum_bytes(&produced));
                let frc = LZ4F_freeDecompressionContext(dctx);
                iter = fold(iter, frc as u64);
            }

            let frc = LZ4F_freeCompressionContext(cctx);
            iter = fold(iter, frc as u64);
            if !cdict.is_null() {
                LZ4F_freeCDict(cdict);
            }
            if !cdict2.is_null() {
                LZ4F_freeCDict(cdict2);
            }

            if LZ4F_isError(last_err as usize) != 0 {
                let code = LZ4F_getErrorCode(last_err as usize);
                let name = LZ4F_getErrorName(last_err as usize);
                iter = fold(iter, code as u64);
                iter = fold(iter, (!name.is_null()) as u64);
                if !name.is_null() {
                    iter = fold(iter, checksum_bytes(CStr::from_ptr(name).to_bytes()));
                }
            }

            digest = fold(digest, iter);
        }
    }

    format!(
        "op=lz4_frame_compress_roundtrip err={} digest={:016x}",
        last_err, digest
    )
}

fn op_lz4_legacy_api_mix(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0i32;

    for _ in 0..iters {
        unsafe {
            let mut iter = 0u64;
            let src_len = as_c_int_len(data.len());
            let bound = LZ4_compressBound(src_len);
            iter = fold(iter, bound as u64);
            if bound <= 0 {
                last_err = bound;
                digest = fold(digest, iter ^ 13);
                continue;
            }

            let mut out = vec![0u8; bound as usize];
            let csz = LZ4_compress_default(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const i8
                },
                out.as_mut_ptr() as *mut i8,
                src_len,
                bound,
            );
            iter = fold(iter, csz as u64);
            last_err = csz;

            if csz > 0 {
                let mut d1 = vec![0u8; data.len()];
                let u1 = LZ4_uncompress(
                    out.as_ptr() as *const i8,
                    if d1.is_empty() {
                        ptr::null_mut()
                    } else {
                        d1.as_mut_ptr() as *mut i8
                    },
                    src_len,
                );
                iter = fold(iter, u1 as u64);
                if u1 >= 0 {
                    iter = fold(iter, checksum_bytes(&d1));
                }

                let mut d2 = vec![0u8; data.len()];
                let u2 = LZ4_uncompress_unknownOutputSize(
                    out.as_ptr() as *const i8,
                    if d2.is_empty() {
                        ptr::null_mut()
                    } else {
                        d2.as_mut_ptr() as *mut i8
                    },
                    csz,
                    src_len,
                );
                iter = fold(iter, u2 as u64);
                if u2 > 0 {
                    iter = fold(iter, checksum_bytes(&d2[..u2 as usize]));
                }
                last_err = u2;
            }

            digest = fold(digest, iter);
        }
    }

    format!("op=lz4_legacy_api_mix err={} digest={:016x}", last_err, digest)
}

fn op_lz4_file_roundtrip(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0u64;

    for _ in 0..iters {
        unsafe {
            let mut iter = 0u64;
            let mut prefs = zeroed_prefs();
            prefs.compressionLevel = 4;
            prefs.frameInfo.blockMode = LZ4F_blockLinked;
            prefs.frameInfo.blockSizeID = LZ4F_max256KB;
            prefs.frameInfo.contentChecksumFlag = LZ4F_contentChecksumEnabled;
            prefs.frameInfo.contentSize = data.len() as u64;

            let tmp = std::env::temp_dir();
            let in_path = tmp.join("lz4_raw_harness_in.tmp");
            let out_path = tmp.join("lz4_raw_harness_out.tmp");

            let mut ok_paths = 1u64;
            if fs::write(&in_path, data).is_err() {
                ok_paths = 0;
            }
            iter = fold(iter, ok_paths);

            let mut writer: *mut LZ4_writeFile_t = ptr::null_mut();
            let mut reader: *mut LZ4_readFile_t = ptr::null_mut();

            let mut compressed = Vec::new();

            if let Ok(mut f) = fs::File::create(&out_path) {
                let fp = (&mut f as *mut fs::File).cast();
                let wrc =
                    LZ4F_writeOpen(&mut writer as *mut *mut _, fp, &prefs as *const _ as *const _);
                iter = fold(iter, wrc as u64);
                last_err = wrc as u64;
                if LZ4F_isError(wrc) == 0 && !writer.is_null() {
                    let wsz = LZ4F_write(
                        writer,
                        if data.is_empty() {
                            ptr::null()
                        } else {
                            data.as_ptr() as *const _
                        },
                        data.len(),
                    );
                    iter = fold(iter, wsz as u64);
                    last_err = wsz as u64;
                    let wcl = LZ4F_writeClose(writer);
                    iter = fold(iter, wcl as u64);
                    last_err = wcl as u64;
                    writer = ptr::null_mut();
                }
            }

            if let Ok(bytes) = fs::read(&out_path) {
                compressed = bytes;
                iter = fold(iter, compressed.len() as u64);
                iter = fold(iter, checksum_bytes(&compressed));
            }

            if let Ok(mut f) = fs::File::open(&out_path) {
                let fp = (&mut f as *mut fs::File).cast();
                let rrc = LZ4F_readOpen(&mut reader as *mut *mut _, fp);
                iter = fold(iter, rrc as u64);
                last_err = rrc as u64;
                if !reader.is_null() {
                    let mut out = Vec::new();
                    loop {
                        let mut buf = vec![0u8; 32 * 1024];
                        let got = LZ4F_read(reader, buf.as_mut_ptr() as *mut _, buf.len());
                        iter = fold(iter, got as u64);
                        if got == 0 {
                            break;
                        }
                        if got > buf.len() {
                            break;
                        }
                        out.extend_from_slice(&buf[..got]);
                    }
                    iter = fold(iter, out.len() as u64);
                    iter = fold(iter, checksum_bytes(&out));
                    let rcl = LZ4F_readClose(reader);
                    iter = fold(iter, rcl as u64);
                    last_err = rcl as u64;
                    reader = ptr::null_mut();
                }
            }

            let _ = fs::remove_file(&in_path);
            let _ = fs::remove_file(&out_path);

            digest = fold(digest, iter);
        }
    }

    format!("op=lz4_file_roundtrip err={} digest={:016x}", last_err, digest)
}

fn op_xxhash_streaming(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0u32;

    for _ in 0..iters {
        unsafe {
            let mut iter = 0u64;
            let ver = XXH_versionNumber();
            iter = fold(iter, ver as u64);

            let seed32 = 0x1234_5678u32;
            let seed64 = 0x0123_4567_89ab_cdefu64;

            let h32 = XXH32(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const _
                },
                data.len(),
                seed32,
            );
            let h64 = XXH64(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const _
                },
                data.len(),
                seed64,
            );
            iter = fold(iter, h32 as u64);
            iter = fold(iter, h64);

            let s32 = XXH32_createState();
            let s32b = XXH32_createState();
            iter = fold(iter, (!s32.is_null()) as u64);
            iter = fold(iter, (!s32b.is_null()) as u64);

            if !s32.is_null() && !s32b.is_null() {
                let rc = XXH32_reset(s32, seed32);
                iter = fold(iter, rc as u64);
                last_err = rc;

                let p1 = data.len() / 3;
                let p2 = (data.len() * 2) / 3;
                let rc1 = XXH32_update(
                    s32,
                    if p1 == 0 {
                        ptr::null()
                    } else {
                        data[..p1].as_ptr() as *const _
                    },
                    p1,
                );
                let rc2 = XXH32_update(
                    s32,
                    if p2 > p1 {
                        data[p1..p2].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    p2.saturating_sub(p1),
                );
                XXH32_copyState(s32b, s32);
                let rc3 = XXH32_update(
                    s32,
                    if data.len() > p2 {
                        data[p2..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p2),
                );
                let rc4 = XXH32_update(
                    s32b,
                    if data.len() > p2 {
                        data[p2..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p2),
                );
                iter = fold(iter, rc1 as u64);
                iter = fold(iter, rc2 as u64);
                iter = fold(iter, rc3 as u64);
                iter = fold(iter, rc4 as u64);
                last_err = rc4;

                let d32 = XXH32_digest(s32);
                let d32b = XXH32_digest(s32b);
                iter = fold(iter, d32 as u64);
                iter = fold(iter, d32b as u64);
                iter = fold(iter, (d32 == h32) as u64);
                iter = fold(iter, (d32b == h32) as u64);

                let mut canon32 = MaybeUninit::<XXH32_canonical_t>::zeroed();
                XXH32_canonicalFromHash(canon32.as_mut_ptr(), d32);
                let rt32 = XXH32_hashFromCanonical(canon32.as_ptr());
                iter = fold(iter, rt32 as u64);
                iter = fold(iter, (rt32 == d32) as u64);

                let frc1 = XXH32_freeState(s32);
                let frc2 = XXH32_freeState(s32b);
                iter = fold(iter, frc1 as u64);
                iter = fold(iter, frc2 as u64);
            } else {
                if !s32.is_null() {
                    let frc = XXH32_freeState(s32);
                    iter = fold(iter, frc as u64);
                }
                if !s32b.is_null() {
                    let frc = XXH32_freeState(s32b);
                    iter = fold(iter, frc as u64);
                }
            }

            let s64 = XXH64_createState();
            let s64b = XXH64_createState();
            iter = fold(iter, (!s64.is_null()) as u64);
            iter = fold(iter, (!s64b.is_null()) as u64);

            if !s64.is_null() && !s64b.is_null() {
                let rc = XXH64_reset(s64, seed64);
                iter = fold(iter, rc as u64);
                last_err = rc;

                let p1 = data.len() / 4;
                let p2 = data.len() / 2;
                let p3 = (data.len() * 3) / 4;
                let rc1 = XXH64_update(
                    s64,
                    if p1 == 0 {
                        ptr::null()
                    } else {
                        data[..p1].as_ptr() as *const _
                    },
                    p1,
                );
                let rc2 = XXH64_update(
                    s64,
                    if p2 > p1 {
                        data[p1..p2].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    p2.saturating_sub(p1),
                );
                let rc3 = XXH64_update(
                    s64,
                    if p3 > p2 {
                        data[p2..p3].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    p3.saturating_sub(p2),
                );
                XXH64_copyState(s64b, s64);
                let rc4 = XXH64_update(
                    s64,
                    if data.len() > p3 {
                        data[p3..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p3),
                );
                let rc5 = XXH64_update(
                    s64b,
                    if data.len() > p3 {
                        data[p3..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p3),
                );
                iter = fold(iter, rc1 as u64);
                iter = fold(iter, rc2 as u64);
                iter = fold(iter, rc3 as u64);
                iter = fold(iter, rc4 as u64);
                iter = fold(iter, rc5 as u64);
                last_err = rc5;

                let d64 = XXH64_digest(s64);
                let d64b = XXH64_digest(s64b);
                iter = fold(iter, d64);
                iter = fold(iter, d64b);
                iter = fold(iter, (d64 == h64) as u64);
                iter = fold(iter, (d64b == h64) as u64);

                let mut canon64 = MaybeUninit::<XXH64_canonical_t>::zeroed();
                XXH64_canonicalFromHash(canon64.as_mut_ptr(), d64);
                let rt64 = XXH64_hashFromCanonical(canon64.as_ptr());
                iter = fold(iter, rt64);
                iter = fold(iter, (rt64 == d64) as u64);

                let frc1 = XXH64_freeState(s64);
                let frc2 = XXH64_freeState(s64b);
                iter = fold(iter, frc1 as u64);
                iter = fold(iter, frc2 as u64);
            } else {
                if !s64.is_null() {
                    let frc = XXH64_freeState(s64);
                    iter = fold(iter, frc as u64);
                }
                if !s64b.is_null() {
                    let frc = XXH64_freeState(s64b);
                    iter = fold(iter, frc as u64);
                }
            }

            iter = fold(iter, checksum_bytes(data));
            digest = fold(digest, iter);
        }
    }

    format!("op=xxhash_streaming err={} digest={:016x}", last_err, digest)
}

