fn make_frame_bytes(src: &[u8]) -> Vec<u8> {
    unsafe {
        let mut prefs = zeroed_prefs();
        prefs.compressionLevel = 3;
        prefs.autoFlush = 0;
        prefs.frameInfo.blockMode = LZ4F_blockLinked;
        prefs.frameInfo.blockSizeID = LZ4F_max256KB;
        prefs.frameInfo.contentChecksumFlag = LZ4F_contentChecksumEnabled;
        prefs.frameInfo.blockChecksumFlag = LZ4F_blockChecksumEnabled;
        prefs.frameInfo.contentSize = src.len() as u64;

        let bound = LZ4F_compressFrameBound(src.len(), &prefs as *const _);
        if bound == 0 {
            return Vec::new();
        }
        let mut out = vec![0u8; bound];
        let written = LZ4F_compressFrame(
            out.as_mut_ptr() as *mut _,
            out.len(),
            if src.is_empty() {
                ptr::null()
            } else {
                src.as_ptr() as *const _
            },
            src.len(),
            &prefs as *const _,
        );
        if LZ4F_isError(written) != 0 || written > out.len() {
            Vec::new()
        } else {
            out.truncate(written);
            out
        }
    }
}

fn make_frame_bytes_streaming(src: &[u8], dict: &[u8], use_cdict: bool) -> Vec<u8> {
    unsafe {
        let mut prefs = zeroed_prefs();
        prefs.compressionLevel = 9;
        prefs.autoFlush = 0;
        prefs.frameInfo.blockMode = LZ4F_blockLinked;
        prefs.frameInfo.blockSizeID = LZ4F_max256KB;
        prefs.frameInfo.contentChecksumFlag = LZ4F_contentChecksumEnabled;
        prefs.frameInfo.blockChecksumFlag = LZ4F_blockChecksumEnabled;
        prefs.frameInfo.contentSize = src.len() as u64;

        let mut cctx: *mut LZ4F_cctx = ptr::null_mut();
        let crc = LZ4F_createCompressionContext(&mut cctx as *mut *mut _, LZ4F_getVersion());
        if LZ4F_isError(crc) != 0 || cctx.is_null() {
            return Vec::new();
        }

        let bound = LZ4F_compressFrameBound(src.len(), &prefs as *const _).saturating_add(2048);
        let mut out = vec![0u8; bound];
        let mut pos = 0usize;
        let mut hdr = vec![0u8; 256];

        let hsz = if use_cdict {
            let cdict = LZ4F_createCDict(
                if dict.is_empty() {
                    ptr::null()
                } else {
                    dict.as_ptr() as *const _
                },
                dict.len(),
            );
            if cdict.is_null() {
                LZ4F_compressBegin(
                    cctx,
                    hdr.as_mut_ptr() as *mut _,
                    hdr.len(),
                    &prefs as *const _,
                )
            } else {
                let rc = LZ4F_compressBegin_usingCDict(
                    cctx,
                    hdr.as_mut_ptr() as *mut _,
                    hdr.len(),
                    cdict,
                    &prefs as *const _,
                );
                LZ4F_freeCDict(cdict);
                rc
            }
        } else {
            LZ4F_compressBegin_usingDict(
                cctx,
                hdr.as_mut_ptr() as *mut _,
                hdr.len(),
                if dict.is_empty() {
                    ptr::null()
                } else {
                    dict.as_ptr() as *const _
                },
                dict.len(),
                &prefs as *const _,
            )
        };

        if LZ4F_isError(hsz) != 0 || hsz > hdr.len() {
            let _ = LZ4F_freeCompressionContext(cctx);
            return Vec::new();
        }
        out[pos..pos + hsz].copy_from_slice(&hdr[..hsz]);
        pos += hsz;

        let mut copts = zeroed_copts();
        copts.stableSrc = 1;

        let mut off = 0usize;
        while off < src.len() {
            let end = (off + 32 * 1024).min(src.len());
            let part = &src[off..end];
            let need = LZ4F_compressBound(part.len(), &prefs as *const _).saturating_add(64);
            if pos + need > out.len() {
                out.resize(pos + need, 0);
            }
            let wsz = LZ4F_compressUpdate(
                cctx,
                out[pos..].as_mut_ptr() as *mut _,
                out.len() - pos,
                part.as_ptr() as *const _,
                part.len(),
                &copts as *const _,
            );
            if LZ4F_isError(wsz) != 0 {
                let _ = LZ4F_freeCompressionContext(cctx);
                return Vec::new();
            }
            pos += wsz;
            off = end;
        }

        let fsz = LZ4F_flush(
            cctx,
            out[pos..].as_mut_ptr() as *mut _,
            out.len() - pos,
            &copts as *const _,
        );
        if LZ4F_isError(fsz) != 0 {
            let _ = LZ4F_freeCompressionContext(cctx);
            return Vec::new();
        }
        pos += fsz;

        let esz = LZ4F_compressEnd(
            cctx,
            out[pos..].as_mut_ptr() as *mut _,
            out.len() - pos,
            &copts as *const _,
        );
        let _ = LZ4F_freeCompressionContext(cctx);
        if LZ4F_isError(esz) != 0 {
            return Vec::new();
        }
        pos += esz;
        out.truncate(pos);
        out
    }
}

fn op_lz4_block_roundtrip(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0i32;

    for _ in 0..iters {
        unsafe {
            let mut iter = checksum_bytes(data);
            iter = fold(iter, LZ4_versionNumber() as u64);

            let vstr = LZ4_versionString();
            iter = fold(iter, (!vstr.is_null()) as u64);
            if !vstr.is_null() {
                iter = fold(iter, checksum_bytes(CStr::from_ptr(vstr).to_bytes()));
            }

            let src_len = as_c_int_len(data.len());
            let bound = LZ4_compressBound(src_len);
            iter = fold(iter, bound as u64);
            iter = fold(iter, LZ4_sizeofState() as u64);
            iter = fold(iter, LZ4_sizeofStreamState() as u64);

            if data.is_empty() || bound <= 0 {
                last_err = bound;
                digest = fold(digest, iter);
                continue;
            }

            let mut compressed = vec![0u8; bound as usize];
            let csz = LZ4_compress_default(
                data.as_ptr() as *const i8,
                compressed.as_mut_ptr() as *mut i8,
                src_len,
                bound,
            );
            last_err = csz;
            iter = fold(iter, csz as u64);

            if csz > 0 {
                let mut decomp = vec![0u8; data.len()];
                let dsz = LZ4_decompress_safe(
                    compressed.as_ptr() as *const i8,
                    decomp.as_mut_ptr() as *mut i8,
                    csz,
                    src_len,
                );
                last_err = dsz;
                iter = fold(iter, dsz as u64);
                iter = fold(iter, (dsz == src_len && decomp == data) as u64);
                if dsz > 0 {
                    iter = fold(iter, checksum_bytes(&decomp[..dsz as usize]));
                }

                let mut fast = vec![0u8; data.len()];
                let fsz = LZ4_decompress_fast(
                    compressed.as_ptr() as *const i8,
                    fast.as_mut_ptr() as *mut i8,
                    src_len,
                );
                last_err = fsz;
                iter = fold(iter, fsz as u64);
                iter = fold(iter, checksum_bytes(&fast));

                let mut partial = vec![0u8; data.len()];
                let target = as_c_int_len(data.len() / 2 + data.len() % 2);
                let psz = LZ4_decompress_safe_partial(
                    compressed.as_ptr() as *const i8,
                    partial.as_mut_ptr() as *mut i8,
                    csz,
                    target,
                    src_len,
                );
                last_err = psz;
                iter = fold(iter, psz as u64);
                if psz > 0 {
                    iter = fold(iter, checksum_bytes(&partial[..psz as usize]));
                }
            }

            let state_sz = LZ4_sizeofState();
            if state_sz > 0 {
                let mut state = vec![0u8; state_sz as usize];
                let mut out2 = vec![0u8; bound.max(1) as usize];

                let c2 = LZ4_compress_fast_extState(
                    state.as_mut_ptr() as *mut _,
                    data.as_ptr() as *const i8,
                    out2.as_mut_ptr() as *mut i8,
                    src_len,
                    bound,
                    2,
                );
                last_err = c2;
                iter = fold(iter, c2 as u64);

                let c3 = LZ4_compress_fast_extState_fastReset(
                    state.as_mut_ptr() as *mut _,
                    data.as_ptr() as *const i8,
                    out2.as_mut_ptr() as *mut i8,
                    src_len,
                    bound,
                    3,
                );
                last_err = c3;
                iter = fold(iter, c3 as u64);

                let mut src_size = src_len;
                let c4 = LZ4_compress_destSize(
                    data.as_ptr() as *const i8,
                    out2.as_mut_ptr() as *mut i8,
                    &mut src_size,
                    (bound / 2).max(1),
                );
                last_err = c4;
                iter = fold(iter, c4 as u64);
                iter = fold(iter, src_size as u64);

                let mut src_size2 = src_len;
                let c5 = LZ4_compress_destSize_extState(
                    state.as_mut_ptr() as *mut _,
                    data.as_ptr() as *const i8,
                    out2.as_mut_ptr() as *mut i8,
                    &mut src_size2,
                    (bound / 2).max(1),
                    4,
                );
                last_err = c5;
                iter = fold(iter, c5 as u64);
                iter = fold(iter, src_size2 as u64);
            }

            let (dict_len, body_len) = split_for_dict(data);
            let enc = LZ4_createStream();
            let dec = LZ4_createStreamDecode();
            iter = fold(iter, (!enc.is_null()) as u64);
            iter = fold(iter, (!dec.is_null()) as u64);

            if !enc.is_null() && !dec.is_null() && dict_len > 0 && body_len > 0 {
                let body = &data[dict_len..dict_len + body_len];
                let cap = LZ4_compressBound(as_c_int_len(body.len()));
                if cap > 0 {
                    let loaded = LZ4_loadDict(enc, data.as_ptr() as *const i8, as_c_int_len(dict_len));
                    let setd = LZ4_setStreamDecode(dec, data.as_ptr() as *const i8, as_c_int_len(dict_len));
                    iter = fold(iter, loaded as u64);
                    iter = fold(iter, setd as u64);

                    let mut c = vec![0u8; cap as usize];
                    let csz2 = LZ4_compress_fast_continue(
                        enc,
                        body.as_ptr() as *const i8,
                        c.as_mut_ptr() as *mut i8,
                        as_c_int_len(body.len()),
                        cap,
                        1,
                    );
                    last_err = csz2;
                    iter = fold(iter, csz2 as u64);

                    if csz2 > 0 {
                        let mut d = vec![0u8; body.len()];
                        let dsz2 = LZ4_decompress_safe_continue(
                            dec,
                            c.as_ptr() as *const i8,
                            d.as_mut_ptr() as *mut i8,
                            csz2,
                            as_c_int_len(d.len()),
                        );
                        last_err = dsz2;
                        iter = fold(iter, dsz2 as u64);
                        iter = fold(iter, (dsz2 == as_c_int_len(body.len()) && d == body) as u64);
                        if dsz2 > 0 {
                            iter = fold(iter, checksum_bytes(&d[..dsz2 as usize]));
                        }
                    }

                    let mut saved = vec![0u8; dict_len.max(1)];
                    let saved_sz =
                        LZ4_saveDict(enc, saved.as_mut_ptr() as *mut i8, as_c_int_len(saved.len()));
                    iter = fold(iter, saved_sz as u64);
                }
            }

            if !enc.is_null() {
                let rc = LZ4_freeStream(enc);
                iter = fold(iter, rc as u64);
            }
            if !dec.is_null() {
                let rc = LZ4_freeStreamDecode(dec);
                iter = fold(iter, rc as u64);
            }

            digest = fold(digest, iter);
        }
    }

    format!("op=lz4_block_roundtrip err={} digest={:016x}", last_err, digest)
}

fn op_lz4_frame_decompress(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0u64;

    for _ in 0..iters {
        unsafe {
            let mut iter = checksum_bytes(data);
            iter = fold(iter, LZ4F_getVersion() as u64);

            let mut dctx: *mut LZ4F_dctx = ptr::null_mut();
            let rc = LZ4F_createDecompressionContext(&mut dctx as *mut *mut _, LZ4F_getVersion());
            iter = fold(iter, rc as u64);
            last_err = rc as u64;
            if LZ4F_isError(rc) != 0 || dctx.is_null() {
                digest = fold(digest, iter);
                continue;
            }

            let dctx2 =
                LZ4F_createDecompressionContext_advanced(zeroed_custom_mem(), LZ4F_getVersion());
            iter = fold(iter, (!dctx2.is_null()) as u64);
            if !dctx2.is_null() {
                iter = fold(iter, LZ4F_dctx_size(dctx2) as u64);
                let frc = LZ4F_freeDecompressionContext(dctx2);
                iter = fold(iter, frc as u64);
            }

            iter = fold(iter, LZ4F_dctx_size(dctx) as u64);

            if !data.is_empty() {
                let hdr = LZ4F_headerSize(data.as_ptr() as *const _, data.len());
                iter = fold(iter, hdr as u64);

                let mut fi = MaybeUninit::<LZ4F_frameInfo_t>::zeroed();
                let mut src_sz = data.len();
                let info_rc = LZ4F_getFrameInfo(
                    dctx,
                    fi.as_mut_ptr(),
                    data.as_ptr() as *const _,
                    &mut src_sz,
                );
                iter = fold(iter, info_rc as u64);
                iter = fold(iter, src_sz as u64);
                last_err = info_rc as u64;

                if LZ4F_isError(info_rc) == 0 {
                    let info = fi.assume_init();
                    iter = fold(iter, info.blockSizeID as u64);
                    iter = fold(iter, info.blockMode as u64);
                    iter = fold(iter, info.contentChecksumFlag as u64);
                    iter = fold(iter, info.blockChecksumFlag as u64);
                    iter = fold(iter, info.contentSize);
                    iter = fold(iter, info.dictID as u64);

                    let mut produced = Vec::<u8>::new();
                    let mut consumed = src_sz.min(data.len());
                    let mut steps = 0u64;
                    while consumed < data.len() && steps < 1_000_000 {
                        steps += 1;
                        let mut dst = vec![0u8; 64 * 1024];
                        let mut dst_sz = dst.len();
                        let mut src_part = data.len() - consumed;
                        let drc = LZ4F_decompress(
                            dctx,
                            dst.as_mut_ptr() as *mut _,
                            &mut dst_sz,
                            data[consumed..].as_ptr() as *const _,
                            &mut src_part,
                            ptr::null(),
                        );
                        iter = fold(iter, drc as u64);
                        iter = fold(iter, src_part as u64);
                        iter = fold(iter, dst_sz as u64);
                        last_err = drc as u64;

                        if dst_sz > 0 {
                            produced.extend_from_slice(&dst[..dst_sz]);
                        }
                        consumed = consumed.saturating_add(src_part);

                        if LZ4F_isError(drc) != 0 || drc == 0 || (src_part == 0 && dst_sz == 0) {
                            break;
                        }
                    }
                    iter = fold(iter, produced.len() as u64);
                    iter = fold(iter, checksum_bytes(&produced));

                    LZ4F_resetDecompressionContext(dctx);
                    let mut produced2 = Vec::<u8>::new();
                    let mut consumed2 = 0usize;
                    let mut steps2 = 0u64;
                    let mut dopts = zeroed_dopts();
                    dopts.stableDst = 1;
                    while consumed2 < data.len() && steps2 < 1_000_000 {
                        steps2 += 1;
                        let mut dst = vec![0u8; 32 * 1024];
                        let mut dst_sz = dst.len();
                        let mut src_part = data.len() - consumed2;
                        let drc = LZ4F_decompress_usingDict(
                            dctx,
                            dst.as_mut_ptr() as *mut _,
                            &mut dst_sz,
                            data[consumed2..].as_ptr() as *const _,
                            &mut src_part,
                            ptr::null(),
                            0,
                            &dopts as *const _,
                        );
                        iter = fold(iter, drc as u64);
                        iter = fold(iter, src_part as u64);
                        iter = fold(iter, dst_sz as u64);
                        if dst_sz > 0 {
                            produced2.extend_from_slice(&dst[..dst_sz]);
                        }
                        consumed2 = consumed2.saturating_add(src_part);
                        if LZ4F_isError(drc) != 0 || drc == 0 || (src_part == 0 && dst_sz == 0) {
                            break;
                        }
                    }
                    iter = fold(iter, produced2.len() as u64);
                    iter = fold(iter, checksum_bytes(&produced2));
                } else {
                    let code = LZ4F_getErrorCode(info_rc);
                    let name = LZ4F_getErrorName(info_rc);
                    iter = fold(iter, code as u64);
                    iter = fold(iter, (!name.is_null()) as u64);
                    if !name.is_null() {
                        iter = fold(iter, checksum_bytes(CStr::from_ptr(name).to_bytes()));
                    }
                }
            }

            let frc = LZ4F_freeDecompressionContext(dctx);
            iter = fold(iter, frc as u64);
            if LZ4F_isError(frc) != 0 {
                last_err = frc as u64;
            }

            digest = fold(digest, iter);
        }
    }

    format!("op=lz4_frame_decompress err={} digest={:016x}", last_err, digest)
}

fn op_lz4_hc_block_roundtrip(data: &[u8], iters: u64) -> String {
