                LZ4_resetStreamHC(stream, 9);
                LZ4_setCompressionLevel(stream, 10);
                LZ4_favorDecompressionSpeed(stream, 0);

                let loaded = LZ4_loadDictHC(
                    stream,
                    if dict_len == 0 {
                        ptr::null()
                    } else {
                        data.as_ptr() as *const i8
                    },
                    as_c_int_len(dict_len),
                );
                last_err = loaded;
                iter = fold(iter, loaded as u64);

                if dict_len > 0 && body_len > 0 {
                    let body = &data[dict_len..dict_len + body_len];
