                    let mut copts = zeroed_copts();
                    copts.stableSrc = 1;

                    let p1 = data.len() / 3;
                    let p2 = (data.len() * 2) / 3;
                    for part in [&data[..p1], &data[p1..p2], &data[p2..]] {
                        let need =
                            LZ4F_compressBound(part.len(), &prefs as *const _).saturating_add(64);
                        if pos + need > out.len() {
                            out.resize(pos + need, 0);
                        }
                        let wsz = LZ4F_compressUpdate(
                            cctx,
                            out[pos..].as_mut_ptr() as *mut _,
                            out.len() - pos,
                            if part.is_empty() {
                                ptr::null()
                            } else {
                                part.as_ptr() as *const _
                            },
                            part.len(),
                            &copts as *const _,
                        );
                        iter = fold(iter, wsz as u64);
                        last_err = wsz as u64;
                        if LZ4F_isError(wsz) != 0 {
                            break;
                        }
                        pos += wsz;
                    }

                    let fsz = LZ4F_flush(
                        cctx,
                        out[pos..].as_mut_ptr() as *mut _,
                        out.len() - pos,
                        &copts as *const _,
                    );
                    iter = fold(iter, fsz as u64);
                    last_err = fsz as u64;
                    if LZ4F_isError(fsz) == 0 {
                        pos += fsz;
                    }

                    let esz = LZ4F_compressEnd(
                        cctx,
                        out[pos..].as_mut_ptr() as *mut _,
                        out.len() - pos,
                        &copts as *const _,
                    );
                    iter = fold(iter, esz as u64);
                    last_err = esz as u64;
                    if LZ4F_isError(esz) == 0 {
                        pos += esz;
                    }
                    out.truncate(pos);
                    iter = fold(iter, checksum_bytes(&out));

                    let mut dctx: *mut LZ4F_dctx = ptr::null_mut();
                    let drc =
                        LZ4F_createDecompressionContext(&mut dctx as *mut *mut _, LZ4F_getVersion());
                    iter = fold(iter, drc as u64);
                    if LZ4F_isError(drc) == 0 && !dctx.is_null() {
                        let mut produced = Vec::new();
                        let mut consumed = 0usize;
                        while consumed < out.len() {
                            let mut dst = vec![0u8; 64 * 1024];
                            let mut dst_sz = dst.len();
                            let mut src_sz = out.len() - consumed;
                            let r = LZ4F_decompress(
                                dctx,
                                dst.as_mut_ptr() as *mut _,
                                &mut dst_sz,
                                out[consumed..].as_ptr() as *const _,
                                &mut src_sz,
                                ptr::null(),
                            );
                            iter = fold(iter, r as u64);
                            iter = fold(iter, src_sz as u64);
                            iter = fold(iter, dst_sz as u64);
                            if dst_sz > 0 {
                                produced.extend_from_slice(&dst[..dst_sz]);
                            }
                            consumed += src_sz;
                            if LZ4F_isError(r) != 0 || r == 0 || (src_sz == 0 && dst_sz == 0) {
                                break;
                            }
                        }
                        iter = fold(iter, produced.len() as u64);
                        iter = fold(iter, checksum_bytes(&produced));
                        let frc = LZ4F_freeDecompressionContext(dctx);
                        iter = fold(iter, frc as u64);
                    }
                }

                if !cdict.is_null() {
                    let mut tmp = vec![0u8; bound.max(1)];
                    let sz = LZ4F_compressFrame_usingCDict(
                        cctx,
                        tmp.as_mut_ptr() as *mut _,
                        tmp.len(),
                        if data.is_empty() {
                            ptr::null()
                        } else {
                            data.as_ptr() as *const _
                        },
                        data.len(),
                        cdict,
                        &prefs as *const _,
                    );
                    iter = fold(iter, sz as u64);
                    if LZ4F_isError(sz) == 0 && sz <= tmp.len() {
                        tmp.truncate(sz);
                        iter = fold(iter, checksum_bytes(&tmp));
                    }
                }

                if !cdict2.is_null() {
                    let mut hdr2 = vec![0u8; 256];
                    let h2 = LZ4F_compressBegin_usingCDict(
                        cctx,
                        hdr2.as_mut_ptr() as *mut _,
                        hdr2.len(),
                        cdict2,
                        &prefs as *const _,
                    );
                    iter = fold(iter, h2 as u64);
                }

                let mut hdr3 = vec![0u8; 256];
                let h3 = LZ4F_compressBegin_usingDict(
                    cctx,
                    hdr3.as_mut_ptr() as *mut _,
                    hdr3.len(),
                    if dict.is_empty() {
                        ptr::null()
                    } else {
                        dict.as_ptr() as *const _
                    },
                    dict.len(),
                    &prefs as *const _,
                );
                iter = fold(iter, h3 as u64);

                let frc = LZ4F_freeCompressionContext(cctx);
                iter = fold(iter, frc as u64);
            }

            if !cdict.is_null() {
                LZ4F_freeCDict(cdict);
            }
            if !cdict2.is_null() {
                LZ4F_freeCDict(cdict2);
            }

            digest = fold(digest, iter);
        }
    }

    format!(
        "op=lz4_frame_compress_roundtrip err={} digest={:016x}",
        last_err, digest
    )
}

fn op_lz4_legacy_api_mix(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0i32;

    for _ in 0..iters {
        unsafe {
            let mut iter = checksum_bytes(data);
            let src_len = as_c_int_len(data.len());
            let bound = LZ4_compressBound(src_len);
            iter = fold(iter, bound as u64);

            if data.is_empty() || bound <= 0 {
                last_err = bound;
                digest = fold(digest, iter);
                continue;
            }

            let mut out = vec![0u8; bound as usize];
            let csz = LZ4_compress_default(
                data.as_ptr() as *const i8,
                out.as_mut_ptr() as *mut i8,
                src_len,
                bound,
            );
            last_err = csz;
            iter = fold(iter, csz as u64);

            if csz > 0 {
                let mut d1 = vec![0u8; data.len()];
                let u1 = LZ4_uncompress(
                    out.as_ptr() as *const i8,
                    d1.as_mut_ptr() as *mut i8,
                    src_len,
                );
                iter = fold(iter, u1 as u64);
                if u1 >= 0 {
                    iter = fold(iter, checksum_bytes(&d1));
                }

                let mut d2 = vec![0u8; data.len()];
                let u2 = LZ4_uncompress_unknownOutputSize(
                    out.as_ptr() as *const i8,
                    d2.as_mut_ptr() as *mut i8,
                    csz,
                    src_len,
                );
                last_err = u2;
                iter = fold(iter, u2 as u64);
                if u2 > 0 {
                    iter = fold(iter, checksum_bytes(&d2[..u2 as usize]));
                }
            }

            digest = fold(digest, iter);
        }
    }

    format!("op=lz4_legacy_api_mix err={} digest={:016x}", last_err, digest)
}

fn fopen_path(path: &Path, mode: &str) -> *mut CFile {
    let c_path = match CString::new(path.to_string_lossy().as_bytes()) {
        Ok(s) => s,
        Err(_) => return ptr::null_mut(),
    };
    let c_mode = match CString::new(mode) {
        Ok(s) => s,
        Err(_) => return ptr::null_mut(),
    };
    unsafe { fopen(c_path.as_ptr(), c_mode.as_ptr()) }
}

fn op_lz4_file_roundtrip(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0u64;

    for _ in 0..iters {
        unsafe {
            let mut iter = checksum_bytes(data);
            let mut prefs = zeroed_prefs();
            prefs.compressionLevel = 4;
            prefs.frameInfo.blockMode = LZ4F_blockLinked;
            prefs.frameInfo.blockSizeID = LZ4F_max256KB;
            prefs.frameInfo.contentChecksumFlag = LZ4F_contentChecksumEnabled;
            prefs.frameInfo.contentSize = data.len() as u64;

            let tmp = std::env::temp_dir();
            let out_path = tmp.join("lz4_raw_harness_file_roundtrip.tmp.lz4");

            let mut writer: *mut LZ4_writeFile_t = ptr::null_mut();
            let mut reader: *mut LZ4_readFile_t = ptr::null_mut();

            let fpw = fopen_path(&out_path, "wb");
            iter = fold(iter, (!fpw.is_null()) as u64);
            if !fpw.is_null() {
                let wrc =
                    LZ4F_writeOpen(&mut writer as *mut *mut _, fpw as *mut _, &prefs as *const _);
                iter = fold(iter, wrc as u64);
                last_err = wrc as u64;

                if LZ4F_isError(wrc) == 0 && !writer.is_null() {
                    let wsz = LZ4F_write(
                        writer,
                        if data.is_empty() {
                            ptr::null()
                        } else {
                            data.as_ptr() as *const _
                        },
                        data.len(),
                    );
                    iter = fold(iter, wsz as u64);
                    last_err = wsz as u64;

                    let wcl = LZ4F_writeClose(writer);
                    iter = fold(iter, wcl as u64);
                    last_err = wcl as u64;
                    writer = ptr::null_mut();
                }

                let crc = fclose(fpw);
                iter = fold(iter, crc as u64);
            }

            if let Ok(bytes) = fs::read(&out_path) {
                iter = fold(iter, bytes.len() as u64);
                iter = fold(iter, checksum_bytes(&bytes));
            }

            let fpr = fopen_path(&out_path, "rb");
            iter = fold(iter, (!fpr.is_null()) as u64);
            if !fpr.is_null() {
                let rrc = LZ4F_readOpen(&mut reader as *mut *mut _, fpr as *mut _);
                iter = fold(iter, rrc as u64);
                last_err = rrc as u64;

                if !reader.is_null() {
                    let mut out = Vec::new();
                    let mut steps = 0u64;
                    loop {
                        steps += 1;
                        if steps > 1_000_000 {
                            break;
                        }
                        let mut buf = vec![0u8; 32 * 1024];
                        let got = LZ4F_read(reader, buf.as_mut_ptr() as *mut _, buf.len());
                        iter = fold(iter, got as u64);
                        if got == 0 || got > buf.len() {
                            break;
                        }
                        out.extend_from_slice(&buf[..got]);
                    }
                    iter = fold(iter, out.len() as u64);
                    iter = fold(iter, checksum_bytes(&out));

                    let rcl = LZ4F_readClose(reader);
                    iter = fold(iter, rcl as u64);
                    last_err = rcl as u64;
                    reader = ptr::null_mut();
                }

                let crc = fclose(fpr);
                iter = fold(iter, crc as u64);
            }

            let _ = fs::remove_file(&out_path);
            digest = fold(digest, iter);
        }
    }

    format!("op=lz4_file_roundtrip err={} digest={:016x}", last_err, digest)
}

fn op_xxhash_streaming(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0u32;

    for _ in 0..iters {
        unsafe {
            let mut iter = checksum_bytes(data);
            iter = fold(iter, XXH_versionNumber() as u64);

            let seed32 = 0x1234_5678u32;
            let seed64 = 0x0123_4567_89ab_cdefu64;

            let h32 = XXH32(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const _
                },
                data.len(),
                seed32,
            );
            let h64 = XXH64(
                if data.is_empty() {
                    ptr::null()
                } else {
                    data.as_ptr() as *const _
                },
                data.len(),
                seed64,
            );
            iter = fold(iter, h32 as u64);
            iter = fold(iter, h64);

            let s32 = XXH32_createState();
            let s32b = XXH32_createState();
            iter = fold(iter, (!s32.is_null()) as u64);
            iter = fold(iter, (!s32b.is_null()) as u64);
            if !s32.is_null() && !s32b.is_null() {
                let rc = XXH32_reset(s32, seed32);
                iter = fold(iter, rc as u64);
                last_err = rc;

                let p1 = data.len() / 3;
                let p2 = (data.len() * 2) / 3;
                let rc1 = XXH32_update(
                    s32,
                    if p1 == 0 {
                        ptr::null()
                    } else {
                        data[..p1].as_ptr() as *const _
                    },
                    p1,
                );
                let rc2 = XXH32_update(
                    s32,
                    if p2 > p1 {
                        data[p1..p2].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    p2.saturating_sub(p1),
                );
                XXH32_copyState(s32b, s32);
                let rc3 = XXH32_update(
                    s32,
                    if data.len() > p2 {
                        data[p2..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p2),
                );
                let rc4 = XXH32_update(
                    s32b,
                    if data.len() > p2 {
                        data[p2..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p2),
                );
                iter = fold(iter, rc1 as u64);
                iter = fold(iter, rc2 as u64);
                iter = fold(iter, rc3 as u64);
                iter = fold(iter, rc4 as u64);
                last_err = rc4;

                let d32 = XXH32_digest(s32);
                let d32b = XXH32_digest(s32b);
                iter = fold(iter, d32 as u64);
                iter = fold(iter, d32b as u64);
                iter = fold(iter, (d32 == h32) as u64);
                iter = fold(iter, (d32b == h32) as u64);

                let mut canon32 = MaybeUninit::<XXH32_canonical_t>::zeroed();
                XXH32_canonicalFromHash(canon32.as_mut_ptr(), d32);
                let rt32 = XXH32_hashFromCanonical(canon32.as_ptr());
                iter = fold(iter, rt32 as u64);
                iter = fold(iter, (rt32 == d32) as u64);

                let frc1 = XXH32_freeState(s32);
                let frc2 = XXH32_freeState(s32b);
                iter = fold(iter, frc1 as u64);
                iter = fold(iter, frc2 as u64);
            } else {
                if !s32.is_null() {
                    let frc = XXH32_freeState(s32);
                    iter = fold(iter, frc as u64);
                }
                if !s32b.is_null() {
                    let frc = XXH32_freeState(s32b);
                    iter = fold(iter, frc as u64);
                }
            }

            let s64 = XXH64_createState();
            let s64b = XXH64_createState();
            iter = fold(iter, (!s64.is_null()) as u64);
            iter = fold(iter, (!s64b.is_null()) as u64);
            if !s64.is_null() && !s64b.is_null() {
                let rc = XXH64_reset(s64, seed64);
                iter = fold(iter, rc as u64);
                last_err = rc;

                let p1 = data.len() / 4;
                let p2 = data.len() / 2;
                let p3 = (data.len() * 3) / 4;
                let rc1 = XXH64_update(
                    s64,
                    if p1 == 0 {
                        ptr::null()
                    } else {
                        data[..p1].as_ptr() as *const _
                    },
                    p1,
                );
                let rc2 = XXH64_update(
                    s64,
                    if p2 > p1 {
                        data[p1..p2].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    p2.saturating_sub(p1),
                );
                let rc3 = XXH64_update(
                    s64,
                    if p3 > p2 {
                        data[p2..p3].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    p3.saturating_sub(p2),
                );
                XXH64_copyState(s64b, s64);
                let rc4 = XXH64_update(
                    s64,
                    if data.len() > p3 {
                        data[p3..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p3),
                );
                let rc5 = XXH64_update(
                    s64b,
                    if data.len() > p3 {
                        data[p3..].as_ptr() as *const _
                    } else {
                        ptr::null()
                    },
                    data.len().saturating_sub(p3),
                );
                iter = fold(iter, rc1 as u64);
                iter = fold(iter, rc2 as u64);
                iter = fold(iter, rc3 as u64);
                iter = fold(iter, rc4 as u64);
                iter = fold(iter, rc5 as u64);
                last_err = rc5;

                let d64 = XXH64_digest(s64);
                let d64b = XXH64_digest(s64b);
                iter = fold(iter, d64);
                iter = fold(iter, d64b);
                iter = fold(iter, (d64 == h64) as u64);
                iter = fold(iter, (d64b == h64) as u64);

                let mut canon64 = MaybeUninit::<XXH64_canonical_t>::zeroed();
                XXH64_canonicalFromHash(canon64.as_mut_ptr(), d64);
                let rt64 = XXH64_hashFromCanonical(canon64.as_ptr());
                iter = fold(iter, rt64);
                iter = fold(iter, (rt64 == d64) as u64);

                let frc1 = XXH64_freeState(s64);
                let frc2 = XXH64_freeState(s64b);
                iter = fold(iter, frc1 as u64);
                iter = fold(iter, frc2 as u64);
            } else {
                if !s64.is_null() {
                    let frc = XXH64_freeState(s64);
                    iter = fold(iter, frc as u64);
                }
                if !s64b.is_null() {
                    let frc = XXH64_freeState(s64b);
                    iter = fold(iter, frc as u64);
                }
            }

            digest = fold(digest, iter);
        }
    }

    format!("op=xxhash_streaming err={} digest={:016x}", last_err, digest)
}

