pub fn gen_seeds(dir: &str) -> Vec<String> {
    let mut lines = Vec::new();

    let raw1 = realistic_text_payload(220);
    let raw2 = realistic_binary_payload(320);
    let raw3 = realistic_mixed_payload(180);
    let frame1 = make_frame_bytes(&raw1);
    let frame2 = make_frame_bytes_streaming(&raw3, &raw3[..raw3.len().min(4096)], true);

    let seeds: [(&str, &Vec<u8>, &Vec<u8>); 7] = [
        ("lz4_block_roundtrip", &raw1, &raw2),
        ("lz4_frame_decompress", &frame1, &frame2),
        ("lz4_hc_block_roundtrip", &raw2, &raw3),
        ("lz4_frame_compress_roundtrip", &raw1, &raw3),
        ("lz4_legacy_api_mix", &raw1, &raw2),
        ("lz4_file_roundtrip", &raw2, &raw3),
        ("xxhash_streaming", &raw1, &raw2),
    ];

    for (op, a, b) in seeds {
        let p1 = format!("{}/{}.1.bin", dir, op);
        let p2 = format!("{}/{}.2.bin", dir, op);
        let _ = fs::write(&p1, a);
        let _ = fs::write(&p2, b);
        lines.push(format!("seed {} {}", op, p1));
        lines.push(format!("seed {} {}", op, p2));
    }

    lines
}

pub fn gen_perf(dir: &str) -> Vec<String> {
    let mut lines = Vec::new();

    let big_text = realistic_text_payload(40_000);
    let big_bin = realistic_binary_payload(45_000);
    let big_mix = {
        let mut v = Vec::with_capacity(big_text.len() + big_bin.len() + 1024);
        v.extend_from_slice(&big_text);
        v.extend_from_slice(b"\n====\n");
        v.extend_from_slice(&big_bin);
        v.extend_from_slice(b"\nfooter=done repeated repeated repeated repeated\n");
        v
    };

    for (op, bytes) in [
        ("lz4_block_roundtrip", &big_mix),
        ("lz4_hc_block_roundtrip", &big_mix),
        ("lz4_frame_compress_roundtrip", &big_mix),
        ("lz4_legacy_api_mix", &big_mix),
        ("lz4_file_roundtrip", &big_mix),
        ("xxhash_streaming", &big_mix),
    ] {
        let path = format!("{}/{}.perf.bin", dir, op);
        let _ = fs::write(&path, bytes);
        lines.push(format!("perf {} {}", op, path));
    }

    let frame = make_frame_bytes_streaming(&big_mix, &big_mix[..big_mix.len().min(8192)], true);
    let frame_path = format!("{}/lz4_frame_decompress.perf.bin", dir);
    let _ = fs::write(&frame_path, &frame);
    lines.push(format!("perf {} {}", "lz4_frame_decompress", frame_path));

    lines
}
