        for j in 0..24usize {
            let x = ((i + j * 13) % 10_000) as u32;
            v.extend_from_slice(format!("k{}=v{};", j % 7, x % 97).as_bytes());
        }
        v.extend_from_slice(b"ENDREC\n");
