}

fn extended_input(data: &[u8], min_len: usize) -> Vec<u8> {
    let mut out = Vec::new();
    let base = if data.is_empty() {
        b"lz4-raw-fallback-data repeated repeated repeated 0123456789\n".as_slice()
    } else {
        data
    };
    let mut i = 0usize;
    while out.len() < min_len {
        out.extend_from_slice(base);
        out.extend_from_slice(format!("SEG{:06}|", i).as_bytes());
        if i % 3 == 0 {
            out.extend_from_slice(b"alpha alpha alpha beta beta gamma gamma gamma\n");
        }
        if i % 5 == 0 {
            out.extend_from_slice(b"{\"event\":\"tick\",\"ok\":true,\"n\":12345}\n");
        }
        i += 1;
    }
    out
}

