                            stream,
                            body.as_ptr() as *const i8,
                            c.as_mut_ptr() as *mut i8,
                            &mut body_src,
                            (cap / 2).max(1),
                        );
                        iter = fold(iter, csz3 as u64);
                        iter = fold(iter, body_src as u64);

                        if csz2 > 0 {
                            let mut d = vec![0u8; body.len()];
                            let dsz = LZ4_decompress_safe_usingDict(
                                c.as_ptr() as *const i8,
                                d.as_mut_ptr() as *mut i8,
